template<class T>
struct rolling_hashing {
	int base, mod;
	vector<long long> p, H;
	int n;
	rolling_hashing(const T &s, int b, int m): base(b), mod(m), n(s.size()) {
		p.assign(n+1, 1);
		H.assign(n+1, 0);
		for (int i = 0; i < n; ++i) {
			H[i+1] = (H[i] * base + s[i]) % mod;
			p[i+1] = (p[i] * base) % mod;
		}
	}
	int get(int l, int r) {
		int res = (H[r+1] - H[l]*p[r-l+1]) % mod;
		if (res < 0) res += mod;
		return res;
	}
};

template<class T>
struct rolling_hashing {
	vector<ll> base, mod; int n, k;
	vector<vector<ll>> p, H;
	rolling_hashing(T s, vector<ll> b, vector<ll> m): base(b), mod(m), n(s.size()), k(b.size()) {
		p.resize(k); H.resize(k);
		for (int j = 0; j < k; j++) {
			p[j].assign(n + 1, 1);
			H[j].assign(n + 1, 0);
			for (int i = 0; i < n; i++) {
				H[j][i + 1] = (H[j][i] * b[j] + s[i]) % mod[j];
				p[j][i + 1] = (p[j][i] * b[j]) % mod[j];
			}
		}
	}
	vector<ll> get(int l, int r) {
		vector<ll> res(k);
		for (int j = 0; j < k; j++) {
			res[j] = (H[j][r + 1] - H[j][l] * p[j][r - l + 1] % mod[j] + mod[j]) % mod[j];
		}
		return res;
	}
};

template<class T> struct KMP {
	T pattern; vector<int> lps;
	KMP(T &pat): pattern(pat) {
		lps.resize(pat.size(), 0);
		int len = 0, i = 1;
		while (i < pattern.size()) {
			if (pattern[i] == pattern[len])
				lps[i++] = ++len;
			else {
				if (len != 0) len = lps[len - 1];
				else lps[i++] = 0;
			}
		}
	}
	vector<int> search(T &text) {
		vector<int> matches;
		int i = 0, j = 0;
		while (i < text.size()) {
			if (pattern[j] == text[i]) {
				i++, j++;
				if (j == pattern.size()) {
					matches.push_back(i - j);
					j = lps[j - 1];
				}
			} else {
				if (j != 0) j = lps[j - 1];
				else i++;
			}
		}
		return matches;
	}
};
template<class T>
vector<int> prefix(T &S) {
	vector<int> P(S.size());
	P[0] = 0;
	for(int i = 1; i < S.size(); ++ i) {
		P[i] = P[i - 1];
		while(P[i] > 0 && S[P[i]] != S[i])
			P[i] = P[P[i] - 1];
		if(S[P[i]] == S[i])
			++ P[i];
	}
	return P;
}

struct Z {
	int n, m;
	vector<int> z;
	Z(string s) {
		n = s.size();
		z.assign(n, 0);
		int l = 0, r = 0;
		for (int i = 1; i < n; i++) {
			if (i <= r)
				z[i] = min(r - i + 1, z[i - l]);
			while (i + z[i] < n && s[z[i]] == s[i + z[i]])
				++z[i];
			if (i + z[i] - 1 > r)
				l = i, r = i + z[i] - 1;
		}
	}
	Z(string p, string t) {
		string s = p + "#" + t;
		n = p.size();
		m = t.size();
		z.assign(n + m + 1, 0);
		int l = 0, r = 0;
		for (int i = 1; i < n + m + 1; i++) {
			if (i <= r)
				z[i] = min(r - i + 1, z[i - l]);
			while (i + z[i] < n + m + 1 && s[z[i]] == s[i + z[i]])
				++z[i];
			if (i + z[i] - 1 > r)
				l = i, r = i + z[i] - 1;
		}
	}
	void p_in_t(vector<int>& ans) {
		for (int i = n + 1; i < n + m + 1; i++) {
			if (z[i] == n)
				ans.push_back(i - n - 1);
		}
	}
};

struct AhoCorasick {
	enum {
		alpha = 26, first = 'a'
	};
	struct Node {
		int back, next[alpha], start = -1, end = -1, nmatches = 0;
		Node(int v) {
			memset(next, v, sizeof(next));
		}
	};
	vector < Node > N;
	vi backp;
	void insert(string & s, int j) {
		assert(!s.empty());
		int n = 0;
		for (char c: s) {
			int & m = N[n].next[c - first];
			if (m == -1) {
				n = m = sz(N);
				N.emplace_back(-1);
			} else n = m;
		}
		if (N[n].end == -1) N[n].start = j;
		backp.push_back(N[n].end);
		N[n].end = j;
		N[n].nmatches++;
	}
	AhoCorasick(vector < string > & pat): N(1, -1) {
		rep(i, 0, sz(pat)) insert(pat[i], i);
		N[0].back = sz(N);
		N.emplace_back(0);
		queue < int > q;
		for (q.push(0); !q.empty(); q.pop()) {
			int n = q.front(), prev = N[n].back;
			rep(i, 0, alpha) {
				int & ed = N[n].next[i], y = N[prev].next[i];
				if (ed == -1) ed = y;
				else {
					N[ed].back = y;
					(N[ed].end == -1 ? N[ed].end : backp[N[ed].start]) = N[y].end;
					N[ed].nmatches += N[y].nmatches;
					q.push(ed);
				}
			}
		}
	}
	vi find(string word) {
		int n = 0;
		vi res;
		for (char c: word) {
			n = N[n].next[c - first];
			res.push_back(N[n].end);
		}
		return res;
	}
	vector < vi > findAll(vector < string > & pat, string word) {
		vi r = find(word);
		vector < vi > res(sz(word));
		rep(i, 0, sz(word)) {
			int ind = r[i];
			while (ind != -1) {
				res[i - sz(pat[ind]) + 1].push_back(ind);
				ind = backp[ind];
			}
		}
		return res;
	}
};

template<class T>
struct manacher {
	vector<int> odd, even;
	T s; int n;
	manacher(T &s): s(s), n(s.size()) {
		odd.resize(n);
		even.resize(n);
		for (int i = 0, l = 0, r = -1; i < n; i++) {
			int k = (i > r) ? 1 : min(odd[l+r-i], r-i+1);
			while (0 <= i-k and i+k < n and s[i-k] == s[i+k]) k++;
			odd[i] = k--;
			if (i+k > r) l = i-k, r = i+k;
		}
		for (int i = 0, l = 0, r = -1; i < n; i++) {
			int k = (i > r) ? 0 : min(even[l + r - i + 1], r - i + 1);
			while (0 <= i - k - 1 and i + k < n && s[i - k - 1] == s[i + k]) k++;
			even[i] = k--;
			if (i + k > r) l = i - k - 1, r = i + k;
		}
	}
	pair<int, int> get(int i) {
		int o = 2 * odd[i] - 1;
		int e = 2 * even[i];
		if (o >= e)
			return {i - odd[i] + 1, i + odd[i] - 1};
		return {i - even[i], i + even[i] - 1};
	}
};

struct trie {
	vector <vector<ll>> tree;
	vector<ll> counts;
	trie() {
		tree.push_back(vector<ll>(26, -1));
		counts.push_back(0);
	};
	void insert(string &s) {
		ll i = 0, u = 0;
		while(i < s.size()){
				char c = s[i];
				if (tree[u][c - 'a'] == -1){
						ll pos = tree.size();
						tree.push_back(vector<ll>(26, -1));
						counts.push_back(0);
						tree[u][c - 'a'] = pos;
				}
				i++;
				u = tree[u][c - 'a'];
		}
		counts[u]++;
	}
	ll search(string &s){
		ll i = 0,u = 0;
		ll count_ends = 0;
		while(i < s.size()){
				char c = s[i];
				if (tree[u][c - 'a'] != -1){
						u = tree[u][c - 'a'];
						i++;
				}else break;
		}
		if(i == s.size()) count_ends += counts[u];
		return count_ends;
	}
};

using ll = long long;
struct SA {
	int n;
	vector<int> C, R, R_, sa, sa_, lcp;
	inline int gr(int i) { return i < n ? R[i] : 0; }
	void csort(int maxv, int k) {
		C.assign(maxv + 1, 0);
		for (int i = 0; i < n; i++) C[gr(i + k)]++;
		for (int i = 1; i < maxv + 1; i++) C[i] += C[i - 1];
		for (int i = n - 1; i >= 0; i--) sa_[--C[gr(sa[i] + k)]] = sa[i];
		sa.swap(sa_);
	}
	void getSA(vector<int>& s) {
		R = R_ = sa = sa_ = vector<int>(n);
		for (ll i = 0; i < n; i++) sa[i] = i;
		sort(sa.begin(), sa.end(), [&s](int i, int j) { return s[i] < s[j]; });
		int r = R[sa[0]] = 1;
		for (ll i = 1; i < n; i++) R[sa[i]] = (s[sa[i]] != s[sa[i - 1]]) ? ++r : r;
		for (int h = 1; h < n && r < n; h <<= 1) {
			csort(r, h);
			csort(r, 0);
			r = R_[sa[0]] = 1;
			for (int i = 1; i < n; i++) {
				if (R[sa[i]] != R[sa[i - 1]] || gr(sa[i] + h) != gr(sa[i - 1] + h)) r++;
				R_[sa[i]] = r;
			}
			R.swap(R_);
		}
	}
	void getLCP(vector<int> &s) {
		lcp.assign(n, 0);
		int k = 0;
		for (ll i = 0; i < n; i++) {
			int r = R[i] - 1;
			if (r == n - 1) {
				k = 0;
				continue;
			}
			int j = sa[r + 1];
			while (i + k < n && j + k < n && s[i + k] == s[j + k]) k++;
			lcp[r] = k;
			if (k) k--;
		}
	}
	SA(vector<int> &s) {
		n = s.size();
		getSA(s);
		getLCP(s);
	}
};

struct SuffixAutomaton {
	struct state {
		int len, link;
		int next[26];
		state(int _len = 0, int _link = -1) : len(_len), link(_link) {
			memset(next, -1, sizeof(next));
		}
	};
	vector<state> st;
	int last;
	SuffixAutomaton() {}
	SuffixAutomaton(const string &s) { init(s); }
	inline int State(int len = 0, int link = -1) {
		st.emplace_back(len, link);
		return st.size() - 1;
	}
	void init(const string &s) {
		st.reserve(2 * s.size());
		last = State();
		for (char c : s)
			extend(c);
	}
	void extend(char _c) {
		int c = _c - 'a', cur = State(st[last].len + 1), P = last;
		while ((P != -1) && (st[P].next[c] == -1)) {
			st[P].next[c] = cur;
			P = st[P].link;
		}
		if (P == -1)
			st[cur].link = 0;
		else {
			int Q = st[P].next[c];
			if (st[P].len + 1 == st[Q].len)
				st[cur].link = Q;
			else {
				int C = State(st[P].len + 1, st[Q].link);
				copy(st[Q].next, st[Q].next + 26, st[C].next);
				while ((P != -1) && (st[P].next[c] == Q)) {
					st[P].next[c] = C;
					P = st[P].link;
				}
				st[Q].link = st[cur].link = C;
			}
		}
		last = cur;
	}
};

string minRotation(string &s) {
	int a = 0, N = s.size();
	string res = s; s += s;
	for (int b = 0; b < N; b++) {
		for (int k = 0; k < N; k++) {
			if (a + k == b || s[a + k] < s[b + k]) {
				b += max(0, k - 1); break;
			}
			if (s[a + k] > s[b + k]) {
				a = b; break;
			}
		}
	}
	rotate(res.begin(), res.begin() + a, res.end());
	return res;
}

template <typename T>
struct min_queue {
	min_stack<T> in, out;
	void push(T x) { in.push(x); }
	bool empty() { return in.empty() and out.empty(); }
	int size() { return in.size() + out.size(); }
	void pop() {
		if (out.empty())
		for (;in.size(); in.pop()) out.push(in.top());
		out.pop();
	}
	T front() {
		if (!out.empty()) return out.top();
		for (;in.size(); in.pop()) out.push(in.top());
		return out.top();
	}
	T getmin() {
		if (in.empty()) return out.getmin();
		if (out.empty()) return in.getmin();
		return min(in.getmin(), out.getmin());
	}
};

template <typename T>
struct min_stack {
	vector<pair<T, T>> S;
	void push(T x) {
		T new_min = S.empty() ? x : min(x, S.back().second);
		S.push_back({x, new_min});
	}
	bool empty() { return S.empty(); }
	int size() { return S.size(); }
	void pop() { S.pop_back(); }
	T top() { return S.back().first; }
	T getmin() { return S.back().second; }
	void swap(min_stack & other) noexcept { S.swap(other.S); }
};

template<typename T>
struct min_deque {
	min_stack<T> l, r, t;
	void rebalance() {
		bool f = false;
		if (r.empty()) {f = true; l.swap(r);}
		int sz = r.size() / 2;
		while (sz--) {t.push(r.top()); r.pop();}
		while (!r.empty()) {l.push(r.top()); r.pop();}
		while (!t.empty()) {r.push(t.top()); t.pop();}
		if (f) l.swap(r);
	}
	int getmin() {
		if (l.empty()) return r.getmin();
		if (r.empty()) return l.getmin();
		return min(l.getmin(), r.getmin());
	}
	bool empty() {return l.empty() and r.empty();}
	int size() {return l.size() + r.size();}
	void push_front(int x) {l.push(x);}
	void push_back(int x) {r.push(x);}
	void pop_front() {if (l.empty()) rebalance(); l.pop();}
	void pop_back() {if (r.empty()) rebalance(); r.pop();}
	int front() {if (l.empty()) rebalance(); return l.top();}
	int back() {if (r.empty()) rebalance(); return r.top();}
	void swap(min_deque &x) {l.swap(x.l); r.swap(x.r);}
};

template<typename T, int MAXLOG>
struct wavelet_tree {
	struct node {
		succinct_indexable_dictionary sid;
		node *ch[2];
		node() = default;
		node(size_t len) : sid(len + 1), ch{nullptr} {}
	};
	node *root;
	node *build(vector<T> &v, vector<T> &rbuff, int bit, int l, int r) {
		if (l >= r or bit == -1) return nullptr;
		node *_node = new node(r-l);
		ll left = 0, right = 0;
		for (ll k = l; k < r; k++) {
			if ((v[k] >> bit) & 1)
				rbuff[right++] = v[k], _node->sid.set(k - l);
			else v[l + left++] = v[k];
		}
		for (int k = 0; k < right; k++) v[l + left + k] = rbuff[k];
		_node->sid.build();
		_node->ch[0] = build(v, rbuff, bit - 1, l, l + left);
		_node->ch[1] = build(v, rbuff, bit - 1, l + left, r);
		return _node;
	}
	wavelet_tree() = default;
	wavelet_tree(vector<T> &v) {
		vector<T> rbuff(v.size());
		root = build(v, rbuff, MAXLOG - 1, 0, v.size());
	}
	int rank(node *t, int l, int r, const T&x, int level) {
		if (l >= r or t == nullptr) return 0;
		if (level == -1) return r-l;
		bool f = (x >> level) & 1;
		l = t->sid.rank(f, l), r = t->sid.rank(f, r);
		return rank(t->ch[f], l, r, x, level-1);
	}
	int rank(const T &x, int r) { return rank(root, 0, r, x, MAXLOG-1); }
	T kth(node *t, int l, int r, int k, int level) {
		if (l >= r || t == nullptr) return 0;
		int cnt = t->sid.rank(false, r) - t->sid.rank(false, l);
		bool f = cnt <= k;
		l = t->sid.rank(f, l), r = t->sid.rank(f, r);
		if (f) return kth(t->ch[f], l, r, k - cnt, level - 1) | (T(1) << level);
		return kth(t->ch[f], l, r, k, level - 1);
	}
	T kth_smallest(int l, int r, int k) {
		return kth(root, l, r+1, k, MAXLOG - 1);
	}
	T kth_largest(int l, int r, int k) {
		return kth(l, r, r - l - k);
	}
	int range_freq(node *t, int l, int r, T upper, int level) {
		if (t == nullptr || l >= r) return 0;
		bool f = ((upper >> level) & 1);
		int ret = 0;
		if (f) ret += t->sid.rank(false, r) - t->sid.rank(false, l);
		l = t->sid.rank(f, l), r = t->sid.rank(f, r);
		return range_freq(t->ch[f], l, r, upper, level - 1) + ret;
	}
	int range_freq(int l, int r, T upper) {
		return range_freq(root, l, r, upper, MAXLOG - 1);
	}
};

struct succinct_indexable_dictionary {
	size_t len, blocks;
	vector<unsigned> bit, sum;
	succinct_indexable_dictionary() = default;
	succinct_indexable_dictionary(size_t len) : len(len), blocks((len + 31)>>5) {
		bit.assign(blocks, 0U);
		sum.assign(blocks, 0U);
	}
	void set(int k) { bit[k >> 5] |= 1U << (k & 31); }
	void build() {
		sum[0] = 0U;
		for (int i = 1; i < blocks; i++)
			sum[i] = sum[i - 1] + __builtin_popcount(bit[i - 1]);
	}
	bool operator[](int k) { return (bool((bit[k >> 5] >> (k & 31)) & 1)); }
	int rank(int k) {
		return (sum[k >> 5] + __builtin_popcount(bit[k >> 5] & ((1U << (k & 31)) - 1)));
	}
	int rank(bool val, int k) { return (val ? rank(k) : k - rank(k)); }
};

using pii = pair<int,int>;
set<pii>::iterator addInterval(set<pii>& is,
		int L, int R) {
	if (L == R) return is.end();
	auto it = is.lower_bound({L, R}), before = it;
	while (it != is.end() && it->first <= R) {
		R = max(R, it->second);
		before = it = is.erase(it);
	}
	if (it != is.begin() && (--it)->second >= L) {
		L = min(L, it->first);
		R = max(R, it->second);
		is.erase(it);
	}
	return is.insert(before, {L, R});
}
void removeInterval(set<pii>& is, int L, int R) {
	if (L == R) return;
	auto it = addInterval(is, L, R);
	auto r2 = it->second;
	if (it->first == L) is.erase(it);
	else (int&)it->second = L;
	if (R != r2) is.emplace(R, r2);
}

struct bit_vector {
	uint64_t size;
	vector< uint64_t > bv;
	bit_vector() : size(0) {}
	uint64_t get(uint64_t i) const {
		uint64_t b = i / 64;
		uint64_t ib = i % 64;
		return (bv[b] & (1ULL << ib)) >> ib;
	}
	void set(uint64_t i) {
		uint64_t b = i / 64;
		uint64_t ib = i % 64;
		bv[b] |= (1ULL << ib);
	}
	void push_back(uint64_t bit) {
		if(size % 64 == 0) bv.push_back(0);
		uint64_t b = size / 64;
		uint64_t ib = size++ % 64;
		bv[b] |= (bit << ib);
	}
	bit_vector operator~() {
		bit_vector bv = *this;
		for(uint64_t i = 0; i < bv.bv.size(); i++)
			bv.bv[i] = ~bv.bv[i];
		if(size % 64)
			for(uint64_t i = size % 64; i < 64; i++)
				bv.bv[bv.bv.size() - 1] &= (~(1ULL << i));
		return bv;
	}
	friend std::ostream& operator<<(std::ostream& os, const bit_vector& bv) {
		for(uint64_t i = 0; i < bv.size; i++) {
			if(bv.bv[i / 64] < (1ULL << 32) && (i % 64) >= 32) cout << 0;
			else cout << ((bv.bv[i / 64] & (1ULL << (i % 64))) ? 1 : 0);
		}
		return os;
	}
	bit_vector& operator=(const bit_vector& o) {
		if (this != &o)
			size = o.size, bv = o.bv;
		return *this;
	}
	bool operator==(const bit_vector& o) const {
		if(size != o.size) return false;
		for(uint64_t i = 0; i < size; i++)
			if(get(i) != o.get(i)) return false;
		return true;
	}
	bool operator<(const bit_vector& o) const {
		for(uint64_t i = 0; i < size && i < o.size; i++)
			if(get(i) != o.get(i)) return get(i) < o.get(i);
		return size < o.size;
	}
	bool operator>(const bit_vector& o) const {
		for(uint64_t i = 0; i < size && i < o.size; i++)
			if(get(i) != o.get(i)) return get(i) > o.get(i);
		return size > o.size;
	}
	bool operator<=(const bit_vector& o) const {
		for(uint64_t i = 0; i < size && i < o.size; i++)
			if(get(i) != o.get(i)) return get(i) <= o.get(i);
		return size <= o.size;
	}
	bool operator>=(const bit_vector& o) const {
		for(uint64_t i = 0; i < size && i < o.size; i++)
			if(get(i) != o.get(i)) return get(i) >= o.get(i);
		return size >= o.size;
	}
};

struct union_find {
	vector<int> e;
	union_find(int n) { e.assign(n, -1); }
	int findSet (int x) {
		return (e[x] < 0 ? x : e[x] = findSet(e[x]));
	}
	bool sameSet (int x, int y) { return findSet(x) == findSet(y); }
	int size (int x) { return -e[findSet(x)]; }
	bool unionSet (int x, int y) {
		x = findSet(x), y = findSet(y);
		if (x == y) return 0;
		if (e[x] > e[y]) swap(x, y);
		e[x] += e[y], e[y] = x;
		return 1;
	}
};

struct op{
	int v,u;
	int v_value,u_value;
	op(int _v,int _v_value,int _u,int _u_value): v(_v),v_value(_v_value),u(_u),u_value(_u_value) {}
};
struct union_find_rb {
	vector<int> e;
	stack<op> ops;
	int comps;
	union_find_rb(){}
	union_find_rb(int n): comps(n) {e.assign(n, -1);}
	int findSet (int x) {
		return (e[x] < 0 ? x : findSet(e[x]));
	}
	bool sameSet (int x, int y) { return findSet(x) == findSet(y); }
	int size (int x) { return -e[findSet(x)]; }
	bool unionSet (int x, int y) {
		x = findSet(x), y = findSet(y);
		if (x == y) return 0;
		if (e[x] > e[y]) swap(x, y);
		ops.push(op(x,e[x],y,e[y])); comps--;
		e[x] += e[y], e[y] = x;
		return 1;
	}
	void rb(){
		if(ops.empty()) return;
		op last = ops.top(); ops.pop();
		e[last.v] = last.v_value;
		e[last.u] = last.u_value;
		comps++;
	}
};

template <typename T, T m_(T, T)>
struct sparse_table {
	int n;
	vector<vector<T>> table;
	sparse_table() {}
	sparse_table(vector<T> &arr) {
		n = arr.size();
		int k = log2_floor(n) + 1;
		table.assign(n, vector<T>(k));
		for (int i = 0; i < n; i++)
			table[i][0] = arr[i];
		for (int j = 1; j < k; j++)
			for (int i = 0; i + (1 << j) <= n; i++)
				table[i][j] = m_(table[i][j-1], table[i+(1<<(j-1))][j-1]);
	}
	T query(int l, int r) {
		int k = log2_floor(r - l + 1);
		return m_(table[l][k], table[r-(1 << k)+1][k]);
	}
	int log2_floor(int n) { return n ? __builtin_clzll(1) - __builtin_clzll(n) : -1; }
};

template <typename T, T (*m_)(T, T)>
struct disjoint_sparse_table{
	static const int MAXLOG = 20;
	vector<T> dp[MAXLOG]; vector<bool> has[MAXLOG];
	disjoint_sparse_table() {}
	disjoint_sparse_table(vector<T> &ar){
		int i, c, h, l, n = (int)ar.size();
		for (h = 0; h <= __lg(n); h++){
			dp[h].resize(n + 1), has[h].resize(n+1);
			for (c = l = 1 << h; c < n + l; c += (l << 1)){
				for (i = c + 1; i <= min(n, c + l); i++) {
					if (!has[h][i-1]) dp[h][i] = ar[i-1];
					else dp[h][i] = m_(dp[h][i - 1], ar[i-1]);
					has[h][i] = 1;
				}
				for (i = min(n, c) - 1; i >= c - l; i--) {
					if (!has[h][i+1]) dp[h][i] = ar[i];
					else dp[h][i] = m_(ar[i], dp[h][i+1]);
					has[h][i] = 1;
				}
			}
		}
	}
	T query(int l, int r){
		int h = __lg(l ^ (r + 1));
		if (!has[h][l]) return dp[h][r+1];
		if (!has[h][r+1]) return dp[h][l];
		return m_(dp[h][l], dp[h][r + 1]);
	}
};

template<class T, T merge(T,T)>
struct range_query {
	int n,sz,ld,bl; vector<int> q;
	vector<vector<T>> st; vector<T> arr;
	range_query(vector<T> & a){
		n = a.size(); sz = log2(n);
		bl = (n+sz-1)/sz; ld = log2(bl); arr = a;
		st.assign(bl,vector<T>(ld+1)); q.resize(n);
		for (int i = 0; i < n; i++){
			st[i/sz][0] = ((i%sz == 0)?a[i]:merge(st[i/sz][0],a[i]));
			int last = a[i]; q[i] = ((i > 0)?q[i-1]:0);
			while (q[i] != 0 && merge(a[i-1-__builtin_ctz(q[i])],last) == last)
				q[i] ^= (1<<__builtin_ctz(q[i]));
			q[i] = (q[i]<<1|1); q[i] &= (1<<sz)-1;
		}
		for (int i = 1; i <= ld; i++)
			for (int j = 0; j < bl-(1<<(i-1)); j++)
				st[j][i] = merge(st[j][i-1],st[j+(1<<(i-1))][i-1]);
	}
	T spquery(int l, int r){
		int lsz = log2(r-l+1);
		return merge(st[l][lsz],st[r-(1<<lsz)+1][lsz]);
	}
	T query(int l, int r){
		if (l/sz == r/sz)
			return arr[r-(31-__builtin_clz(q[r]&((1<<(r-l+1))-1)))];
		T res; bool hasR = 0;
		int ql = (l+sz-1)/sz, qr = (r/sz)-1;
		if (ql <= qr) res = spquery(ql,qr), hasR = 1;
		int pl = ql*sz-1, pr = (qr+1)*sz;
		if (l <= pl){
			int vl = arr[pl-(31-__builtin_clz(q[pl]&((1<<(pl-l+1))-1)))];
			res = (hasR?merge(res,vl):vl), hasR = 1;
		}
		if (pr <= r){
			int vr = arr[r-(31-__builtin_clz(q[r]&((1<<(r-pr+1))-1)))];
			res = (hasR?merge(res,vr):vr), hasR = 1;
		}
		return res;
	}
};

template<class T, T m_(T, T)> struct segment_tree{
	int n; vector<T> ST;
	segment_tree(){}
	segment_tree(vector<T> &a){
		n = a.size(); ST.resize(n << 1);
		for (int i=n;i<(n<<1);i++)ST[i]=a[i-n];
		for (int i=n-1;i>0;i--)ST[i]=m_(ST[i<<1],ST[i<<1|1]);
	}
	void update(int pos, T val){
		ST[pos += n] = val;
		for (pos >>= 1; pos > 0; pos >>= 1)
			ST[pos] = m_(ST[pos<<1], ST[pos<<1|1]);
	}
	T query(int l, int r){
		T ansL, ansR; bool hasL = 0, hasR = 0;
		for (l += n, r += n + 1; l < r; l >>= 1, r >>= 1) {
			if (l & 1)
				ansL=(hasL?m_(ansL,ST[l++]):ST[l++]),hasL=1;
			if (r & 1)
				ansR=(hasR?m_(ST[--r],ansR):ST[--r]),hasR=1;
		}
		if (!hasL) return ansR; if (!hasR) return ansL;
		return m_(ansL, ansR);
	}
};

template<class T, T merge(T,T)>
struct segment_tree2d {
	int n,m; vector<vector<T>> st;
	segment_tree2d(){}
	segment_tree2d(vector<vector<T>> & a){
		n = a.size(), m = a[0].size(); st.assign(n<<1,vector<T>(m<<1));
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < m; j++) st[i+n][j+m] = a[i][j];
			for (int j = m-1; j > 0; j--) st[i+n][j] = merge(st[i+n][j<<1],st[i+n][j<<1|1]);
		}
		for (int i = n-1; i > 0; i--){
			for (int j = 0; j < m; j++) st[i][j+m] = merge(st[i<<1][j+m],st[i<<1|1][j+m]);
			for (int j = m-1; j > 0; j--) st[i][j] = merge(st[i][j<<1],st[i][j<<1|1]);
		}
	}
	void update(int i, int j, T val){
		st[i += n][j += m] = val;
		for (int jj = (j>>1); jj > 0; jj >>= 1)
		st[i][jj] = merge(st[i][jj<<1],st[i][jj<<1|1]);
		for (i >>= 1; i > 0; i >>= 1){
			st[i][j] = merge(st[i<<1][j],st[i<<1|1][j]);
			for (int jj = (j>>1); jj > 0; jj >>= 1)
			st[i][jj] = merge(st[i][jj<<1],st[i][jj<<1|1]);
		}
	}
	T query_help(int i, int l, int r){
		T ansL, ansR; bool hasL = 0, hasR = 0;
		for (l += m, r += m+1; l < r; l >>= 1, r >>= 1){
			if (l&1) ansL = (hasL?merge(ansL,st[i][l++]):st[i][l++]), hasL = 1;
			if (r&1) ansR = (hasR?merge(st[i][--r],ansR):st[i][--r]), hasR = 1;
		}
		if (!hasL) return ansR; if (!hasR) return ansL;
		return merge(ansL,ansR);
	}
	T query(int l1, int r1, int l2, int r2){
		T ansL, ansR; bool hasL = 0, hasR = 0;
		for (l1 += n, r1 += n+1; l1 < r1; l1 >>= 1, r1 >>= 1){
			if (l1&1) ansL = (hasL?merge(ansL,query_help(l1++,l2,r2)):query_help(l1++,l2,r2)), hasL = 1;
			if (r1&1) ansR = (hasR?merge(query_help(--r1,l2,r2),ansR):query_help(--r1,l2,r2)), hasR = 1;
		}
		if (!hasL) return ansR; if (!hasR) return ansL;
		return merge(ansL,ansR);
	}
};

template<class T, T m_(T, T)> struct segment_tree_with_walk : segment_tree<T,m_> {
	int walk(int l, T k) {
		vector<int> L, R;
		int r = this->n - 1;
		for (l += this->n, r += this->n + 1; l < r; l >>= 1, r >>= 1) {
			if (l & 1) L.push_back(l++);
			if (r & 1) R.push_back(--r);
		}
		reverse(R.begin(), R.end());
		L.insert(L.end(), R.begin(), R.end());
		for (int v : L) {
			if (this->ST[v] >= k) {
				while (v < this->n) v = (this->ST[v << 1] >= k) ? (v << 1) : (v << 1 | 1);
				return v - this->n;
			}
		}
		return -1;
	}
};

template<
	class T1,
	class T2,
	T1 merge(T1, T1),
	void pushUpd(T2& , T2& , int, int, int, int),
	void applyUpd(T2&, T1&, int, int)
>
struct segment_tree_lazy{
	vector<T1> ST; vector<T2> lazy; vector<bool> upd;
	int n;
	void build(int i, int l, int r, vector<T1>&values){
		if (l == r){
			ST[i] = values[l];
			return;
		}
		build(i << 1, l, (l + r) >> 1, values);
		build(i << 1 | 1, (l + r) / 2 + 1, r, values);
		ST[i] = merge(ST[i << 1], ST[i << 1 | 1]);
	}
	segment_tree_lazy() {}
	segment_tree_lazy(vector<T1>&values){
		n = values.size(); ST.resize(n << 2 | 3);
		lazy.resize(n << 2 | 3); upd.resize(n << 2 | 3, false);
		build(1, 0, n - 1, values);
	}
	void push(int i, int l, int r){
		if (upd[i]){
			applyUpd(lazy[i], ST[i], l, r);
			if (l != r){
				pushUpd(lazy[i], lazy[i << 1], l, r, l, (l + r) / 2);
				pushUpd(lazy[i], lazy[i << 1 | 1], l, r, (l + r) / 2 + 1, r);
				upd[i << 1] = 1;
				upd[i << 1 | 1] = 1;
			}
			upd[i] = false;
			lazy[i] = T2();
		}
	}
	void update(int i, int l, int r, int a, int b, T2 &u){
		if (l >= a and r <= b){
			pushUpd(u, lazy[i], a, b, l, r);
			upd[i] = true;
		}
		push(i, l, r);
		if (l > b or r < a) return;
		if (l >= a and r <= b) return;
		update(i << 1, l, (l + r) >> 1, a, b, u);
		update(i << 1 | 1, (l + r) / 2 + 1, r, a, b, u);
		ST[i] = merge(ST[i << 1], ST[i << 1 | 1]);
	}
	void update(int a, int b, T2 u){
		if (a > b){
			update(0, b, u);
			update(a, n - 1, u);
			return ;
		}
		update(1, 0, n - 1, a, b, u);
	}
	T1 query(int i, int l, int r, int a, int b){
		push(i, l, r);
		if (a <= l and r <= b)
			return ST[i];
		int mid = (l + r) >> 1;
		if (mid < a)
			return query(i << 1 | 1, mid + 1, r, a, b);
		if (mid >= b)
			return query(i << 1, l, mid, a, b);
		return merge(query(i << 1, l, mid, a, b), query(i << 1 | 1, mid + 1, r, a, b));
	}
	T1 query(int a, int b){
		if (a > b) return merge(query(a, n - 1), query(0, b));
		return query(1, 0, n - 1, a, b);
	}
};

template<class T1,class T2,T1 merge(T1&,T1&),void applyUpd(T1&,T2&,int), void pushUpd(T2&,T2&,int)>
struct segment_tree_lazy {
		int n,h; vector<T1> st; vector<T2> lazy;
		segment_tree_lazy(vector<T1> & a){
				n = a.size(); h = sizeof(int)*8-__builtin_clz(n);
				st.resize(n<<1); lazy.resize(n);
				for (int i = 0; i < n; i++) st[n+i] = a[i];
				for (int i = n-1; i > 0; i--) st[i] = merge(st[i<<1],st[i<<1|1]);
		}
		void calc(int pos, int sz){
				st[pos] = merge(st[pos<<1],st[pos<<1|1]);
				if (lazy[pos].upd()) applyUpd(st[pos],lazy[pos],sz);
		}
		void apply(int pos, T2 val, int sz){
				applyUpd(st[pos],val,sz);
				if (pos < n) pushUpd(val,lazy[pos],sz);
		}
		void push(int l, int r){
				int s = h, sz = 1<<(h-1);
				for (l += n, r += n-1; s > 0; s--, sz >>= 1)
						for (int i = l>>s; i <= r>>s; i++) if (lazy[i].upd()){
								apply(i<<1,lazy[i],sz);
								apply(i<<1|1,lazy[i],sz);
								lazy[i] = T2();
						}
		}
		void update(int l, int r, T2 val){
				push(l,l+1); push(r,r+1);
				bool cl = 0, cr = 0; int sz = 1;
				for (l += n, r += n+1; l < r; l >>= 1, r >>= 1, sz <<= 1){
						if (cl) calc(l-1,sz);
						if (cr) calc(r,sz);
						if (l&1) apply(l++,val,sz), cl = 1;
						if (r&1) apply(--r,val,sz), cr = 1;
				}
				for (--l; r > 0; l >>= 1, r >>= 1, sz <<= 1){
						if (cl) calc(l,sz);
						if (cr && (!cl || l != r)) calc(r,sz);
				}
		}
		T1 query(int l, int r){
				push(l,l+1); push(r,r+1);
				T1 ansL, ansR; bool hasL = 0,hasR = 0;
				for (l += n, r += n+1; l < r; l >>= 1, r >>= 1){
						if (l&1) ansL = (hasL?merge(ansL,st[l++]):st[l++]), hasL = 1;
						if (r&1) ansR = (hasR?merge(st[--r],ansR):st[--r]), hasR = 1;
				}
				if (!hasL) return ansR; if (!hasR) return ansL;
				return merge(ansL,ansR);
		}
};
struct lz {
		ll val;
		lz(){ val = 0; }
		bool upd(){ return (val != 0); }
};
ll merge(ll & a, ll & b){
		return a+b;
}
void applyUpd(ll & v, lz & u, int sz){
		v += u.val*((ll)sz);
}
void pushUpd(lz & u1, lz & u2, int sz){
		u2.val += u1.val;
}

template<class T, T _m(T, T)>
struct persistent_segment_tree {
	vector<T> ST;
	vector<int> L, R;
	int n, rt;
	persistent_segment_tree(int n): ST(1, T()), L(1, 0), R(1, 0), n(n), rt(0) {}
	int new_node(T v, int l = 0, int r = 0) {
		int ks = ST.size();
		ST.push_back(v); L.push_back(l); R.push_back(r);
		return ks;
	}
	int update(int k, int l, int r, int p, T v) {
		int ks = new_node(ST[k], L[k], R[k]);
		if (l == r) {
			ST[ks] = v; return ks;
		}
		int m = (l + r) / 2, ps;
		if (p <= m) {
			ps = update(L[ks], l, m, p, v);
			L[ks] = ps;
		} else {
			ps = update(R[ks], m + 1, r, p, v);
			R[ks] = ps;
		}
		ST[ks] = _m(ST[L[ks]], ST[R[ks]]);
		return ks;
	}
	T query(int k, int l, int r, int a, int b) {
		if (l >= a and r <= b)
			return ST[k];
		int m = (l + r) / 2;
		if (b <= m)
			return query(L[k], l, m, a, b);
		if (a > m)
			return query(R[k], m + 1, r, a, b);
		return _m(query(L[k], l, m, a, b), query(R[k], m + 1, r, a, b));
	}
	int update(int k, int p, T v) {
		return rt = update(k, 0, n - 1, p, v);
	}
	int update(int p, T v) {
		return update(rt, p, v);
	}
	T query(int k, int a, int b) {
		return query(k, 0, n - 1, a, b);
	}
};

template <
		class T,
		class MAXi,
		T merge(T, T),
		T init(MAXi, MAXi)
>
struct dynamic_segment_tree {
	vector<T> ST; vector<int>L, R;
	MAXi n; int n_count;
	dynamic_segment_tree (MAXi n, int r) :
		n(n),n_count(1),L(1),R(1),ST(1){
		ST.reserve(r);
		L.reserve(r);
		R.reserve(r);
		ST[0] = init(0, n - 1);
	}
	int addNode(MAXi l, MAXi r){
		L.push_back(0);
		R.push_back(0);
		ST.push_back(init(l, r));
		return n_count ++;
	}
	T query(int i, MAXi l, MAXi r, MAXi a, MAXi b) {
		if (a <= l and r <= b)
			return ST[i];
		MAXi mid = ((l + r) >> 1LL);
		if (b <= mid)
			return (L[i] != 0 ? query(L[i], l, mid, a, b) : init(l, mid));
		else if (a > mid)
			return (R[i] != 0 ? query(R[i], mid + 1, r, a, b) : init(mid + 1, r));
		if (L[i] == 0) L[i] = addNode(l, mid);
		if (R[i] == 0) R[i] = addNode(mid + 1, r);
		return merge(query(L[i], l, mid, a, b), query(R[i], mid + 1, r, a, b));
	}
	T query(MAXi a, MAXi b) {
		return query(0, 0, n - 1, a, b);
	}
	void update(int i, MAXi l, MAXi r, MAXi p, T v) {
		if (l == r){
			ST[i] = v; return;
		}
		MAXi mid = (l + r) / 2LL;
		if (p <= mid)
			update(L[i] != 0 ? L[i] : L[i] = addNode(l, mid), l, mid, p, v);
		else
			update(R[i] != 0 ? R[i] : R[i] = addNode(mid + 1, r), mid + 1, r, p, v);
		ST[i] = merge(
				L[i] != 0 ? ST[L[i]] : init(l, mid),
				R[i] != 0 ? ST[R[i]] : init(mid + 1, r)
			);
	}
	void update(MAXi pos, T v) {
		update(0, 0, n - 1, pos, v);
	}
};

template<class tree_node, class query_input, class query_output>
struct extended_segment_tree{
	vector<tree_node> ST;
	int n;
	void build(int i, int l, int r, vector<tree_node> &a){
		if (l == r) { ST[i] = a[l]; return; }
		int mid = (l + r) / 2;
		build(i << 1, l, mid, a);
		build(i << 1 | 1, mid + 1, r, a);
		ST[i].build(&ST[i << 1], &ST[i << 1 | 1]);
	}
	extended_segment_tree(vector<tree_node> &a){
		n = a.size(); ST.resize(n << 2 | 3);
		build(1, 0, n - 1, a);
	}
	query_output query(int i, int l, int r, int a, int b, query_input &q){
		if (l >= a and r <= b) { return ST[i].query(q); }
		int mid = (l + r) / 2;
		if (b <= mid) return query(i << 1, l, mid, a, b, q);
		else if (a > mid) return query(i << 1 | 1, mid + 1, r, a, b, q);
		query_output R = query(i << 1 | 1, mid + 1, r, a, b, q);
		query_output L = query(i << 1, l, mid, a, b, q);
		return L.merge(&R);
	}
	query_output query(int l, int r, query_input &q){
		return query(1, 0, n - 1, l, r, q);
	}
	void update(int i, int l, int r, int pos, tree_node &x){
		if (l == r){ ST[i] = x; return; }
		int mid = (l + r) / 2;
		if (l <= mid) update(i << 1, l, mid, pos, x);
		if (r > mid) update(i << 1 | 1, mid + 1, r, pos, x);
		ST[i].update(pos - l, x);
	}
	void update(int pos, tree_node &x){
		update(1, 0, n - 1, pos, x);
	}
};
struct query_output{
	int v;
	query_output(int v) : v(v){}
	query_output merge(query_output *r){
		return query_output(v + r->v);
	}
};
typedef int query_input;
struct tree_node{
	int n;
	vector<int> a;
	tree_node(){}
	tree_node(int x){
		a.resize(1, x);
		n = 1;
	}
	void update(int pos, tree_node &x) {
		return;
	}
	query_output query(int v){
		int left = 0, right = n - 1;
		while(left < right){
			int mid = (left + right + 1) / 2;
			if (a[mid] <= v) left = mid;
			else right = mid - 1;
		}
		if (a[left] > v) left--;
		return query_output(n - 1 - left);
	}
	void build(tree_node *l, tree_node *r){
		int nl = l->a.size(), nr = r->a.size();
		int pl = 0, pr = 0;
		a.reserve(nl + nr);
		while(pl < nl || pr < nr){
			if (pl == nl || (pr < nr and l->a[pl] >= r->a[pr])){
				a.push_back(r->a[pr ++]);
			}
			else{
				a.push_back(l->a[pl ++]);
			}
		}
		n = a.size();
	}
};
