struct query{
	int v,u;
	bool status;
	query(int _v,int _u) : v(_v),u(_u) {};
};
struct query_tree{
	vector<vector<query>> tree;
	int size;
	UnionFindRB uf;
	query_tree(int _size,int n) : size(_size) {uf = UnionFindRB(n); tree.resize(4*_size + 4);}
	void addTree(int v,int l,int r,int ul,int ur, query& q){
		if(ul > ur) return;
		if(l == ul && ur == r){tree[v].push_back(q); return; }
		int mid = (l + r)/2;
		addTree(2*v,l,mid,ul,min(ur,mid),q);
		addTree(2*v + 1,mid + 1,r,max(ul,mid + 1),ur,q);
	}
	void add(query q,int l,int r){addTree(1,0,size - 1,l,r,q);}
	void dfs(int v,int l,int r,vector<int> &ans){
		for(query &q: tree[v]) q.status = uf.unionSet(q.v,q.u);
		if(l == r) ans[l] = uf.comps;
		else{
			int mid = (l + r)/2;
			dfs(2*v,l,mid,ans);
			dfs(2*v + 1,mid + 1,r,ans);
		}
		for(query q: tree[v]) if(q.status) uf.rb();
	}
	vector<int> getAns(){
		vector<int> ans(size);
		dfs(1,0,size - 1,ans);
		return ans;
	}
};

template <class T, T merge(T,T)>
struct sqrt_decomp {
	int n,sq;
	vector<T> st,bl;
	sqrt_decomp(vector<T> & a){
		n = a.size(); st.resize(n);
		sq = sqrtl(n); bl.resize((n+sq-1)/sq);
		for (int i = 0; i < n; i++){
			st[i] = a[i];
			bl[i/sq] = ((i%sq == 0)?st[i]:merge(bl[i/sq],st[i]));
		}
	}
	void update(int pos, T val) {
		st[pos] = val;
		int block = pos/sq, lb = block*sq, rb = min(block*sq+sq-1,n-1);
		T vl;
		for (int i = lb; i <= rb; i++)
			vl = ((i == lb)?st[i]:merge(vl,st[i]));
		bl[block] = vl;
	}
	T query(int l, int r){
		T res; bool hasR = 0;
		for (int i = l/sq; i <= r/sq; i++){
			int lb = i*sq, rb = i*sq+sq-1;
			if (l <= lb && rb <= r){
				res = (hasR?merge(res,bl[i]):bl[i]), hasR = 1;
				continue;
			}
			for (int j = max(l,lb); j <= min(rb,r); j++)
				res = (hasR?merge(res,st[j]):st[j]), hasR = 1;
		}
		return res;
	}
};

template <typename T>
struct merge_sort_tree {
	int N; vector<vector<T>> ST;
	merge_sort_tree(){}
	merge_sort_tree(vector<T> &vs) {
		N = vs.size(); ST.resize(2 * N);
		for (int i = 0; i < N; i++) ST[i + N] = {vs[i]};
		for (int i = N - 1; i > 0; i--)
			merge(ST[i<<1].begin(), ST[i<<1].end(), ST[i<<1|1].begin(), ST[i<<1|1].end(), back_inserter(ST[i]));
	}
	int query(int i, int j, int k) {
		int res = 0;
		for (i += N, j += N + 1; i < j; i >>= 1, j >>= 1) {
			if (i & 1) res += ST[i].size() - (upper_bound(ST[i].begin(), ST[i].end(), k) - ST[i].begin()), i++;
			if (j & 1) --j, res += ST[j].size() - (upper_bound(ST[j].begin(), ST[j].end(), k) - ST[j].begin());
		}
		return res;
	}
};

struct fenwick_tree {
	vector<ll> bit; int n;
	fenwick_tree(int n): n(n) { bit.assign(n, 0); }
	fenwick_tree(vector<ll> &a): fenwick_tree(a.size()) {
		for (size_t i = 0; i < a.size(); i++) {
			bit[i]+=a[i];
			if ((i|(i + 1)) < a.size()) bit[i|(i + 1)]+=bit[i];
		}
	}
	ll sum(int r) {
		ll ret = 0;
		for (; r >= 0; r = (r & (r + 1)) - 1)
			ret += bit[r];
		return ret;
	}
	ll sum(int l, int r) {
		return sum(r) - sum(l - 1);
	}
	void add(int idx, ll delta) {
		for (; idx < n; idx = idx | (idx + 1))
			bit[idx] += delta;
	}
};

struct fenwick_tree_with_walk : fenwick_tree {
	ll walk(ll k) {
		if (k <= 0 || k > sum(n-1)) return n;
		ll i = -1, s = 1;
		while ((s << 1) < n) s <<= 1;
		while (s > 0) {
			ll m = i + s;
			if (m < n && bit[m] < k) {
				i = m;
				k -= bit[m];
			}
			s >>= 1;
		}
		return i + 1;
	}
};

struct fenwick_tree_2d {
	int N, M;
	vector<vector<ll>> BIT;
	fenwick_tree_2d(int N, int M): N(N), M(M) {
		BIT.assign(N + 1, vector<ll>(M + 1, 0));
	}
	void update(int x, int y, ll v) {
		for (int i = x; i <= N; i += (i & -i))
			for (int j = y; j <= M; j += (j & -j))
				BIT[i][j] += v;
	}
	ll sum(int x, int y) {
		ll s = 0;
		for (int i = x; i > 0; i -= (i & -i))
			for (int j = y; j > 0; j -= (j & -j))
				s += BIT[i][j];
		return s;
	}
	ll query(int x1, int y1, int x2, int y2) {
		return sum(x2, y2) - sum(x2, y1 - 1) - sum(x1 - 1, y2) + sum(x1 - 1, y1 - 1);
	}
};

const ll INF = 1e15;
struct Line {
	mutable ll a, b, c;
	bool operator<(Line r) const {
		return a < r.a;
	}
	bool operator<(ll x) const {
		return c < x;
	}
};
struct LineContainer: multiset < Line, less < >> {
	ll div(ll a, ll b) {
		return a / b - ((a ^ b) < 0 && a % b);
	}
	bool isect(iterator x, iterator y) {
		if (y == end()) return x -> c = INF, 0;
		if (x -> a == y -> a) x -> c = x -> b > y -> b ? INF : -INF;
		else x -> c = div(y -> b - x -> b, x -> a - y -> a);
		return x -> c >= y -> c;
	}
	void add(ll a, ll b) {
		auto z = insert({
			a,
			b,
			0
		}), y = z++, x = y;
		while (isect(y, z)) z = erase(z);
		if (x != begin() && isect(--x, y)) isect(x, y = erase(y));
		while ((y = x) != begin() && (--x) -> c >= y -> c) isect(x, erase(y));
	}
	ll query(ll x) {
		if (empty()) return -INF;
		auto l = * lower_bound(x);
		return l.a * x + l.b;
	}
};

template<class T, int d>
struct pt {
		array<T,d> p;
		bool operator!=(const pt &o) const { return p != o.p; }
		T dist(const pt &o) const {
				T res = 0;
				for (int i = 0; i < d; i++)
						res += abs(p[i] - o.p[i]);
				return res;
		}
};
template<class pt, class T, int d>
struct kd_tree {
		struct node {
				int ax; T val; pt p;
				node *izq, *der;
				array<T, d> mn, mx;
		};
		node *root;
		T mn_dist(const pt &q, const array<T,d> & mnb, const array<T, d> &mxb) {
				T dist = 0;
				for (int i = 0; i < d; i++) {
						if (q.p[i] < mnb[i]) dist += mnb[i]-q.p[i];
						else if (q.p[i] > mxb[i]) dist += q.p[i]-mxb[i];
				}
				return dist;
		}
		node *build_tree(vector<pt> &a, int l, int r) {
				if (l > r) return nullptr;
				node *cur = new node();
				array<T, d> minb, maxb;
				for (int i = 0; i < d; i++) {
						minb[i] = a[l].p[i];
						maxb[i] = a[l].p[i];
				}
				for (int j = l + 1; j <= r; j++) {
						for (int i = 0; i < d; i++) {
								if (a[j].p[i] < minb[i]) minb[i] = a[j].p[i];
								if (a[j].p[i] > maxb[i]) maxb[i] = a[j].p[i];
						}
				}
				cur->mn = minb; cur->mx = maxb; int ax = 0;
				T mxld = 0;
				for (int i = 0; i < d; i++) {
						T ld = maxb[i]-minb[i];
						if (ld > mxld) {
								mxld = ld;
								ax = i;
						}
				}
				cur->ax = ax; int mid = (l+r)/2;
				nth_element(a.begin() + l, a.begin() + mid, a.begin() + r + 1, [ax](const pt &x, const pt &y) {
						return x.p[ax] < y.p[ax];
				});
				cur->p = a[mid]; cur->val = a[mid].p[ax];
				cur->izq = build_tree(a, l, mid - 1);
				cur->der = build_tree(a, mid + 1, r);
				return cur;
		}
		kd_tree(vector<pt> &a) {
				root = build_tree(a, 0, a.size() - 1);
		}
		void query(node *cur, const pt &q, T &ans) {
				if (cur == nullptr) return;
				if (q != cur->p) {
						T d_here = q.dist(cur->p);
						if (d_here < ans)
								ans = d_here;
				} else {
						ans = min(ans, (T)0);
				}
				vector<pair<T, node *>> ch;
				if (cur->izq) {
						T d_izq = mn_dist(q, cur->izq->mn, cur->izq->mx);
						ch.push_back({d_izq, cur->izq});
				}
				if (cur->der) {
						T d_der = mn_dist(q, cur->der->mn, cur->der->mx);
						ch.push_back({d_der, cur->der});
				}
				sort(ch.begin(), ch.end(), [](const auto &a, const auto &b) {
						return a.first < b.first;
				});
				for (auto &[d_val, to] : ch)
						if (d_val < ans) query(to, q, ans);
		}
		T query(const pt &q) {
				T ans = numeric_limits<T>::max();
				query(root, q, ans);
				return ans;
		}
};

struct query {
	ll l, r, i;
};
template<class T, typename U, class T2>
struct mo_algorithm {
	vector<U> ans;
	template<typename... Args>
	mo_algorithm(vector<T> &v, vector<query> &queries, Args... args) {
		T2 ds(args...);
		ll block_sz = sqrtl(v.size());
		ans.assign(queries.size(), -1);
		sort(queries.begin(), queries.end(), [&](auto &a, auto &b) {
			return a.l/block_sz != b.l/block_sz ? a.l/block_sz < b.l/block_sz : a.r < b.r;
		});
		ll l = 0, r = -1;
		for (query q : queries) {
			while (l > q.l) ds.add(v[--l]);
			while (r < q.r) ds.add(v[++r]);
			while (l < q.l) ds.remove(v[l++]);
			while (r > q.r) ds.remove(v[r--]);
			ans[q.i] = ds.answer(q);
		}
	}
};

struct query {
	ll l, r, i;
};
template<typename T, typename U, class T2>
struct rollback_mo_algorithm {
	vector<U> ans;
	template<typename... Args>
	rollback_mo_algorithm(vector<T> &v, vector<query> &queries, Args... args) {
		ll block_sz = sqrtl(v.size());
		ans.resize(queries.size());
		T2 ds(args...);
		sort(queries.begin(), queries.end(), [&](auto &a, auto &b) {
			return a.l/block_sz != b.l/block_sz ? a.l/block_sz < b.l/block_sz : a.r < b.r;
		});
		ll t = 0, last, border, last_block = -1, block;
		for(ll i = 0; i < queries.size(); i++) {
			block = queries[i].l / block_sz;
			if (block == queries[i].r/block_sz) {
				T2 tmp(args...);
				for (ll k = queries[i].l; k <= queries[i].r; k++)
					tmp.add(v[k]);
				ans[queries[i].i] = tmp.answer(queries[i]);
				continue;
			}
			if(last_block != block) {
				ds = T2(args...);
				border = block_sz * (block + 1);
				last = border;
			}
			last_block = block;
			for(ll k = last + 1; k <= queries[i].r; k++) ds.add(v[k]);
			t = ds.snapshot();
			for(ll k = queries[i].l; k <= border; k++) ds.add(v[k]);
			ans[queries[i].i] = ds.answer(queries[i]);
			ds.rollback(t);
			last = queries[i].r;
		}
	}
};

struct query {
	int l,r,t,i;
};
template<class T, typename U, class T2>
struct mo_update {
	vector<U> ans;
	mo_update(vector<T> &v, vector<query> &queries, vector<pair<int,T>> & updates, T2 & ds) {
		ds.init(v,updates);
		int block_sz = cbrtl(2*v.size()*v.size());
		ans.assign(queries.size(),-1);
		sort(queries.begin(), queries.end(), [&](auto a, auto b){
			if (a.l/block_sz == b.l/block_sz){
				if (a.r/block_sz == b.r/block_sz) return a.t < b.t;
				return a.r/block_sz < b.r/block_sz;
			}
			return a.l/block_sz < b.l/block_sz;
		});
		int l = 0, r = -1;
		for (query q : queries) {
			while (ds.t < q.t) ds.update(l,r);
			while (ds.t > q.t) ds.rollback(l,r);
			while (l > q.l) ds.add(--l);
			while (r < q.r) ds.add(++r);
			while (l < q.l) ds.remove(l++);
			while (r > q.r) ds.remove(r--);
			ans[q.i] = ds.answer(q);
		}
	}
};

