struct tarjan {
	struct edge { int u, v, comp, bridge; };
	int n, nbc, T;
	vector<vector<int>> adj;
	vector<edge> e;
	vector<int> disc, low, art, st;
	tarjan(int n) : n(n), nbc(0), T(0), adj(n), disc(n, -1), low(n), art(n, 0) {}
	int add_edge(int u, int v) {
		int i = e.size();
		adj[u].push_back(i);
		adj[v].push_back(i);
		e.push_back({u, v, -1, false});
		return i;
	}
	void dfs(int u, int pe) {
		low[u] = disc[u] = T++;
		for (int i : adj[u]) {
			if (i == pe) continue;
			int v = e[i].u ^ e[i].v ^ u;
			if (disc[v] < 0) {
				st.push_back(i);
				dfs(v, i);
				if (low[v] > disc[u])
					e[i].bridge = true;
				if (low[v] >= disc[u]) {
					art[u]++;
					while (st.back() != i) {
						e[st.back()].comp = nbc;
						st.pop_back();
					}
					e[st.back()].comp = nbc;
					st.pop_back();
					nbc++;
				}
				low[u] = min(low[u], low[v]);
			} else if (disc[v] < disc[u]) {
				st.push_back(i);
				low[u] = min(low[u], disc[v]);
			}
		}
	}
	void solve() {
		for (int i = 0; i < n; i++)
			if (disc[i] < 0) dfs(i, -1), art[i]--;
	}
	bool is_bridge(int i) { return e[i].bridge; }
	bool is_art(int v) { return art[v] > 0; }
	int component(int i) { return e[i].comp; }
};

struct tarjan {
	int n,timer;
	vector<bool> vis,ist;
	vector<int> tin,low,st,cmp;
	vector<vector<int>> scc;
	void dfs(int u, vector<vector<int>> & adj){
		vis[u] = ist[u] = 1;
		st.push_back(u); tin[u] = low[u] = timer++;
		for (auto v : adj[u]){
			if (!vis[v]){
				dfs(v,adj);
				low[u] = min(low[u],low[v]);
			} else if (ist[v]){
				low[u] = min(low[u],tin[v]);
			}
		}
		if (low[u] == tin[u]){
			scc.emplace_back(); int cur;
			do {
				cur = st.back(); st.pop_back();
				ist[cur] = 0; scc.back().push_back(cur);
				cmp[cur] = (int)scc.size()-1;
			} while (cur != u);
		}
	}
	tarjan(vector<vector<int>> & adj){
		n = adj.size(); tin.resize(n); timer = 0; cmp.resize(n);
		low.resize(n); vis.resize(n,0); ist.resize(n,0);
		for (int i = 0; i < n; i++) if (!vis[i]) dfs(i,adj);
	}
};

struct Bridges {
	int n, timer;
	vector <int> tin, low, vis;
	vector <pair<int, int>> bridges;
	Bridges(vector <vector<int>> &adj, int root = 0) {
		n = adj.size();
		timer = 0;
		vis.resize(n, false);
		tin.resize(n);
		low.resize(n);
		dfs(root, root, adj);
	}
	void dfs(int v, int p, vector <vector<int>> &adj) {
		vis[v] = 1; tin[v] = low[v] = timer++;
		for (int to: adj[v]) {
			if (to == p) continue;
			if (vis[to]) low[v] = min(low[v], tin[to]);
			else {
				dfs(to, v, adj);
				low[v] = min(low[v], low[to]);
				if (low[to] > tin[v]) bridges.push_back({v,to});
			}
		}
	}
};

struct ArticulationPoints {
	int n, timer;
	vector <int> tin, low, vis;
	set <int> points;
	void dfs(int v, int p, vector<vector<int>> &adj) {
		vis[v] = true; tin[v] = low[v] = timer++;
		int child = 0;
		for (int to: adj[v]) {
			if (to == p) continue;
			if (vis[to]) low[v] = min(low[v], tin[to]);
			else {
				dfs(to, v, adj);
				low[v] = min(low[v], low[to]);
				if ((low[to] >= tin[v]) && (p != -1))
					points.insert(v);
				child++;
			}
		}
		if ((p == -1) && (child > 1)) points.insert(v);
	}
	ArticulationPoints(vector < vector < int >> & adj, int root = 0) {
		n = adj.size();
		vis.resize(n, false);
		tin.resize(n);
		low.resize(n);
		dfs(root, -1, adj);
	}
};

struct dominator_tree {
		int n,l,s;
		vector<int> tin,par,vis_ord, dsu_mn, dsu_par, sdom, dep,rdom,idom;
		vector<bool> vis;
		vector<vector<int>> up;
		vector<vector<pair<int,int>>> up_mn;
		void dfs(int u, int p, vector<vector<int>> & adj){
				if (vis[u]) return;
				vis[u] = 1;
				dep[u] = dep[p]+1;
				tin[u] = vis_ord.size();
				vis_ord.push_back(u);
				par[u] = p;
				for (int v : adj[u]) dfs(v,u,adj);
		}
		int find(int x){
				if (dsu_par[x] == -1) return x;
				if (dsu_par[dsu_par[x]] != -1){
						int res = find(dsu_par[x]);
						if (tin[res] < tin[dsu_mn[x]])
				dsu_mn[x] = res;
			dsu_par[x] = dsu_par[dsu_par[x]];
				}
				assert(dsu_mn[x] != INT32_MAX);
				return dsu_mn[x];
		}
		void get_sdom(vector<vector<int>> & rev){
				for (int i = vis_ord.size()-1; i >= 0; i--){
						int c = vis_ord[i];
						if (c == s) continue;
						for (int to : rev[c]){
								int res = find(to);
								if (sdom[c] == -1 || tin[res] < tin[sdom[c]])
										sdom[c] = res;
						}
						dsu_par[c] = par[c];
						dsu_mn[c] = sdom[c];
						if (sdom[c] == -1) cerr << c << endl;
				}
		}
		void init_up(){
				for (int i = 0; i < n; i++){
						if (!vis[i]) continue;
						up[i][0] = par[i];
						up_mn[i][0] = {tin[sdom[i]],i};
				}
				for (int i = 1; i < l; i++) {
			for (int j = 0; j < n; j++) {
								if (!vis[j]) continue;
				int h = up[j][i-1];
				if (h == -1) {
					up[j][i] = -1;
					up_mn[j][i] = up_mn[j][i-1];
				} else {
					up[j][i] = up[h][i-1];
					up_mn[j][i] = min(up_mn[j][i-1], up_mn[h][i-1]);
				}
			}
		}
		}
		int get_min(int v, int u){
				int dist = dep[u]-dep[v];
				pair<int,int> ret = up_mn[u][0];
				int w = u;
				for (int i = 0; i < l; i++)
						if (dist&(1<<i)){
								ret = min(ret,up_mn[w][i]);
								w = up[w][i];
						}
				assert(w == v);
				return ret.second;
		}
		void get_idom(){
				for (int c : vis_ord){
						if (c == s) continue;
						rdom[c] = get_min(sdom[c],c);
				}
				for (int c : vis_ord)
						if (c != s)
								idom[c] = ((rdom[c] == c)?sdom[c]:idom[rdom[c]]);
		}
		dominator_tree(vector<vector<int>> & adj, vector<vector<int>> & rev, int _s = 0, int logn = 20){
				n = adj.size(); l = logn; s = _s;
				tin.resize(n,INT32_MAX);
				par.resize(n,-1);
				vis.resize(n,0);
				dep.resize(n,0);
				dfs(s,-1,adj);
				dsu_par.resize(n,-1);
				dsu_mn.resize(n,INT32_MAX);
				sdom.resize(n,-1);
				rdom.resize(n,-1);
				idom.resize(n,-1);
				get_sdom(rev);
				up.assign(n,vector<int>(logn));
				up_mn.assign(n,vector<pair<int,int>>(logn));
				init_up();
				get_idom();
		}
};

template<typename T>
struct SCC {
	vector<vector<int>> GT, G, SCC_G, SCC_GT, comp_nodes;
	vector<T> data, cdata;
	stack<int> order;
	vector<int> comp, dp;
	vector<bool> visited;
	T (*cfunc)(T, T);
	int comp_count = 0;
	void topsort(int u) {
		visited[u] = true;
		for (int v : G[u])
			if (!visited[v])
				topsort(v);
			order.push(u);
	}
	void build_component(int u) {
		visited[u] = true;
		for (int v : GT[u])
			if (!visited[v])
				build_component(v);
		comp[u] = comp_count;
		comp_nodes[comp_count].push_back(u);
	}
	void compress_graph() {
		for (int u = 0; u < G.size(); u++)
			cdata[comp[u]] = cfunc(cdata[comp[u]], data[u]);
			for (int u = 0; u < G.size(); u++)
				for (int v : G[u])
					if (comp[u] != comp[v]) {
						SCC_G[comp[u]].push_back(comp[v]);
						SCC_GT[comp[v]].push_back(comp[u]);
					}
	}
	T process(int cmp, T (*func)(T a, T b), T (*merge)(T a, T b)) {
		if (dp[cmp]) return dp[cmp];
		dp[cmp] = cdata[cmp];
		for (int u : SCC_G[cmp])
			dp[cmp] = merge(dp[cmp], func(process(u, func, merge), cdata[cmp]));
		return dp[cmp];
	}
	SCC(vector<vector<int>> &G, vector<T> &data, T (*cfunc)(T a, T b), T comp_identity, T dp_identity): cfunc(cfunc), G(G), data(data) {
		GT.resize(G.size()); comp_nodes.resize(G.size());
		visited.assign(G.size(), 0);
		cdata.assign(G.size(), comp_identity);
		comp.assign(G.size(), 0);
		SCC_G.resize(G.size()); SCC_GT.resize(G.size());
		dp.assign(G.size(), dp_identity);
		for (int u = 0; u < G.size(); u++)
		for (int v : G[u])
			GT[v].push_back(u);
			for (int u = 0; u < G.size(); u++)
				if (!visited[u])
					topsort(u);
		visited.assign(G.size(), 0);
		while (!order.empty()) {
			int u = order.top();
			order.pop();
			if (visited[u]) continue;
			build_component(u);
			comp_count++;
		}
		compress_graph();
	}
};

struct directed_euler_trail {
	ll n, m = 0;
	vector<vector<ll>> adj;
	vector<pair<ll, ll>> E;
	vector<ll> indeg, outdeg, vertices, edges;
	directed_euler_trail(ll n) : n(n), adj(n), indeg(n), outdeg(n) {}
	void add_edge(ll u, ll v) {
		adj[u].push_back(m);
		E.push_back({u, v});
		outdeg[u]++, indeg[v]++, m++;
	}
	ll find_start() {
		ll s = -1, cp = 0, cm = 0;
		for (ll v = 0; v < n; v++) {
			ll d = outdeg[v] - indeg[v];
			if (d == 1) cp++, s = v;
			else if (d == -1) cm++;
			else if (d != 0) return -2;
			if (outdeg[v] > 0 && s < 0) s = v;
		}
		if (cp == 0 && cm == 0) return s;
		return (cp == 1 && cm == 1) ? s : -2;
	}
	bool solve() {
		if (m == 0) { vertices = {0}; return true; }
		ll s = find_start();
		if (s == -2) return false;
		vector<ll> ep(n);
		edges.resize(m);
		ll pp = 0, pq = m, v = s;
		while (pp < pq) {
			if (ep[v] >= (ll)adj[v].size()) {
				if (pp == 0)
					return false;
				edges[--pq] = edges[--pp];
				v = E[edges[pq]].first;
			} else {
				ll e = adj[v][ep[v]++];
				edges[pp++] = e;
				v = E[e].second;
			}
		}
		vertices = {s};
		for (ll e : edges) vertices.push_back(E[e].second);
		return true;
	}
};

struct undirected_euler_trail {
	ll n, m = 0;
	vector<vector<ll>> adj;
	vector<pair<ll, ll>> E;
	vector<ll> deg, vertices, edges;
	undirected_euler_trail(ll n) : n(n), adj(n), deg(n) {}
	void add_edge(ll u, ll v) {
		adj[u].push_back(m);
		if (u != v) adj[v].push_back(m);
		E.push_back({u, v});
		deg[u]++, deg[v]++, m++;
	}
	ll find_start() {
		ll s = -1, codd = 0;
		for (ll v = 0; v < n; v++) {
			if (deg[v]&1) codd++, s = v;
			else if (deg[v] > 0 && s < 0)
				s = v;
		}
		return (codd == 0 || codd == 2) ? s : -2;
	}
	bool solve() {
		if (m == 0) { vertices = {0}; return true; }
		ll s = find_start();
		if (s == -2) return false;
		vector<ll> ep(n);
		edges.resize(m);
		vector<bool> alive(m, true);
		ll pp = 0, pq = m, v = s;
		while (pp < pq) {
			if (ep[v] >= adj[v].size()) {
				if (pp == 0)
					return false;
				edges[--pq] = edges[--pp];
				v ^= E[edges[pq]].first ^ E[edges[pq]].second;
			} else {
				ll e = adj[v][ep[v]++];
				if (!alive[e])
					continue;
				alive[e] = false;
				edges[pp++] = e;
				v ^= E[e].first ^ E[e].second;
			}
		}
		vertices = {s};
		for (ll e : edges) {
			s ^= E[e].first ^ E[e].second;
			vertices.push_back(s);
		}
		return true;
	}
};

struct TwoSat {
	int N;
	vector<vector<int>> gr;
	vector<int> values;
	TwoSat(int n = 0) : N(n), gr(2*n) {}
	int addVar() {
		gr.emplace_back(); gr.emplace_back();
		return N++;
	}
	void either(int f, int j) {
		f = max(2*f, -1-2*f);
		j = max(2*j, -1-2*j);
		gr[f].push_back(j^1);
		gr[j].push_back(f^1);
	}
	void setValue(int x) { either(x, x); }
	void atMostOne(const vector<int>& li) {
		if ((int)li.size() <= 1) return;
		int cur = ~li[0];
		for (int i = 2; i < (int)li.size(); i++) {
			int next = addVar();
			either(cur, ~li[i]);
			either(cur, next);
			either(~li[i], next);
			cur = ~next;
		}
		either(cur, ~li[1]);
	}
	vector<int> val, comp, z; int Time = 0;
	int dfs(int i) {
		int low = val[i] = ++Time, x; z.push_back(i);
		for (int e : gr[i]) if (!comp[e])
			low = min(low, val[e] ? val[e] : dfs(e));
		if (low == val[i]) do {
			x = z.back(); z.pop_back();
			comp[x] = low;
			if (values[x>>1] == -1)
				values[x>>1] = x&1;
		} while (x != i);
		return val[i] = low;
	}
	bool solve() {
		values.assign(N, -1);
		val.assign(2*N, 0); comp = val;
		for (int i = 0; i < 2*N; i++) if (!comp[i]) dfs(i);
		for (int i = 0; i < N; i++)
			if (comp[2*i] == comp[2*i+1]) return false;
		return true;
	}
};

ll count_cycle_4(const vector<vector<ll>>& g) {
	ll n = g.size(), w = 0;
	vector<ll> val(n, 0), deg(n);
	vector<vector<ll>> G(n);
	for (ll i = 0; i < n; i++) deg[i] = g[i].size();
	for (ll i = 0; i < n; i++) {
		for (auto e : g[i]) {
			if (e < i) continue;
			if (deg[i] <= deg[e]) G[i].push_back(e);
			else G[e].push_back(i);
		}
	}
	for (ll i = 0; i < n; i++) {
		for (auto u : g[i]) {
			for (auto v : G[u]) {
				if (deg[v] > deg[i] || (deg[v] == deg[i] && v > i))
					w += val[v]++;
			}
		}
		for (auto u : g[i]) {
			for (auto v : G[u]) {
				val[v] = 0;
			}
		}
	}
	return w;
}

ll count_cycle_3(const vector<vector<ll>>& g) {
	ll n = g.size(), w = 0;
	vector<ll> val(n, 0), deg(n);
	vector<vector<ll>> G(n);
	for (ll i = 0; i < n; i++) deg[i] = g[i].size();
	for (ll i = 0; i < n; i++) {
		for (auto e : g[i]) {
			if (e < i) continue;
			if (deg[i] <= deg[e]) G[i].push_back(e);
			else G[e].push_back(i);
		}
	}
	for (ll i = 0; i < n; i++) {
		for (auto u : G[i]) val[u] = i;
		for (auto e : g[i]) {
			if (e < i) continue;
			for (auto v : G[e])
				if (val == i) {
					w++;
				}
		}
	}
	return w;
}

int chromatic(vector<int> & adj){
		int n = adj.size();
		if (n == 0) return 0;
		ll mod = 998244353, m = (1<<n);
		vector<ll> ind(m),s(m);
		for (int i = 0; i < m; i++)
				s[i] = ((n-__builtin_popcount(i))&1?-1:1);
		ind[0] = 1;
		for (int i = 1; i < m; i++){
				int ctz = __builtin_ctz(i);
				ind[i] = (ind[i-(1<<ctz)]+ind[(i-(1<<ctz))&~adj[ctz]])%mod;
		}
		for (int j = 1; j < n; j++){
				ll sum = 0;
				for (int i = 0; i < m; i++){
						ll cur = (s[i]*ind[i])%mod;
						s[i] = cur;
						sum = (sum+cur)%mod;
				}
				if (sum != 0) return j;
		}
		return n;
}

template <class T> struct chu_liu {
	struct edge {
		int u, v, id;
		T len;
	};
	int n;
	vector<edge> e;
	vector<int> inc, dec, take, pre, num, id, vis;
	vector<T> inw;
	T INF;
	chu_liu(int n) : n(n), pre(n), num(n), id(n), vis(n), inw(n) {
		INF = numeric_limits<T>::max() / 2;
	}
	void add_edge(int x, int y, T w) {
		inc.push_back(0), dec.push_back(0), take.push_back(0);
		e.push_back({x, y, (int)e.size(), w});
	}
	T solve(int root) {
		auto e2 = e;
		T ans = 0;
		int eg = e.size() - 1, pos = eg;
		while (1) {
			for (int i = 0; i < n; i++)
				inw[i] = INF, id[i] = vis[i] = -1;
			for (auto &ed : e2)
				if (ed.len < inw[ed.v])
					inw[ed.v] = ed.len, pre[ed.v] = ed.u, num[ed.v] = ed.id;
			inw[root] = 0;
			for (int i = 0; i < n; i++)
				if (inw[i] == INF)
					return -1;
			int tot = -1;
			for (int i = 0; i < n; i++) {
				ans += inw[i];
				if (i != root)
					take[num[i]]++;
				int j = i;
				while (vis[j] != i && j != root && id[j] < 0)
					vis[j] = i, j = pre[j];
				if (j != root && id[j] < 0) {
					id[j] = ++tot;
					for (int k = pre[j]; k != j; k = pre[k])
						id[k] = tot;
				}
			}
			if (tot < 0)
				break;
			for (int i = 0; i < n; i++)
				if (id[i] < 0)
					id[i] = ++tot;
			n = tot + 1;
			int j = 0;
			for (int i = 0; i < (int)e2.size(); i++) {
				int v = e2[i].v;
				e2[j] = {id[e2[i].u], id[e2[i].v], e2[i].id, e2[i].len - inw[v]};
				if (e2[j].u != e2[j].v) {
					inc.push_back(e2[i].id);
					dec.push_back(num[v]);
					take.push_back(0);
					e2[j++].id = ++pos;
				}
			}
			e2.resize(j);
			root = id[root];
		}
		while (pos > eg) {
			if (take[pos])
				take[inc[pos]]++, take[dec[pos]]--;
			pos--;
		}
		return ans;
	}
};

template <class T> struct fast_chu_liu {
	struct edge {
		int u, v;
		T len;
	};
	struct node {
		edge key;
		node *l = nullptr, *r = nullptr;
		T delta = 0;
		node(edge e) : key(e) {}
		void prop() {
			key.len += delta;
			if (l) l->delta += delta;
			if (r) r->delta += delta;
			delta = 0;
		}
		edge top() {
			prop();
			return key;
		}
	};
	int n;
	vector<edge> e;
	fast_chu_liu(int n) : n(n) {}
	void add_edge(int x, int y, T w) { e.push_back({x, y, w}); }
	node *merge(node *a, node *b) {
		if (!a || !b)
			return a ? a : b;
		a->prop(), b->prop();
		if (a->key.len > b->key.len)
			swap(a, b);
		swap(a->l, (a->r = merge(b, a->r)));
		return a;
	}
	void pop(node *&a) {
		a->prop();
		a = merge(a->l, a->r);
	}
	pair<T, vector<int>> solve(int root) {
		union_find_rb uf(n);
		vector<node *> heap(n, nullptr);
		for (edge &ed : e)
			heap[ed.v] = merge(heap[ed.v], new node(ed));
		T ans = 0;
		vector<int> seen(n, -1), path(n), par(n);
		seen[root] = root;
		vector<edge> Q(n), in(n, {-1, -1, 0});
		deque<tuple<int, int, vector<edge>>> cycs;
		for (int s = 0; s < n; s++) {
			int u = s, qi = 0, w;
			while (seen[u] < 0) {
				if (!heap[u])
					return {-1, {}};
				edge ed = heap[u]->top();
				heap[u]->delta -= ed.len, pop(heap[u]);
				Q[qi] = ed, path[qi++] = u, seen[u] = s;
				ans += ed.len, u = uf.findSet(ed.u);
				if (seen[u] == s) {
					node *cyc = nullptr;
					int end = qi, t = (int)uf.ops.size();
					do
						cyc = merge(cyc, heap[w = path[--qi]]);
					while (uf.unionSet(u, w));
					u = uf.findSet(u), heap[u] = cyc, seen[u] = -1;
					cycs.push_front({u, t, {&Q[qi], &Q[end]}});
				}
			}
			for (int i = 0; i < qi; i++)
				in[uf.findSet(Q[i].v)] = Q[i];
		}
		for (auto &[u, t, comp] : cycs) {
			while ((int)uf.ops.size() > t)
				uf.rb();
			edge inEdge = in[u];
			for (auto &ed : comp)
				in[uf.findSet(ed.v)] = ed;
			in[uf.findSet(inEdge.v)] = inEdge;
		}
		for (int i = 0; i < n; i++)
			par[i] = in[i].u;
		return {ans, par};
	}
};

template<typename T, T f(T)>
pair<ll, ll> tortoise_hare(T x0) {
	T t = f(x0); T h = f(f(x0));
	while(t != h) t = f(t), h = f(f(h));
	ll mu = 0; t = x0;
	while(t != h) t = f(t), h = f(h), mu++;
	ll lam = 1; h = f(t);
	while(t != h)h = f(h), lam += 1;
	return {mu, lam};
}

template <typename T> struct point2d {
	T x, y;
	point2d(){};
	point2d(T x_, T y_) : x(x_), y(y_) {}
	point2d<T> &operator+=(point2d<T> t) {
		x += t.x, y += t.y;
		return *this;
	}
	point2d<T> operator-(point2d<T> t) { return {x - t.x, y - t.y}; }
	point2d<T> operator+(point2d<T> t) { return {x + t.x, y + t.y}; }
	point2d<T> operator*(T t) { return {x * t, y * t}; }
	point2d<T> operator/(T t) { return {x / t, y / t}; }
	point2d<T> &operator-=(point2d<T> t) {
		x -= t.x, y -= t.y;
		return *this;
	}
	T operator|(point2d<T> b) { return x * b.x + y * b.y; }
	T operator^(point2d<T> b) { return x * b.y - y * b.x; }
	T cross(point2d<T> a, point2d<T> b) { return (a - *this) ^ (b - *this); }
	T norm() { return (*this) | (*this); }
	T sqdist(point2d<T> b) { return ((*this) - b).norm(); }
	double abs() { return sqrt(norm()); }
};
template <typename T> point2d<T> operator*(T a, point2d<T> b) { return b * a; }

template <typename T> struct point3d {
	T x, y, z;
	point3d() : x(0), y(0), z(0) {}
	point3d(T x_, T y_, T z_) : x(x_), y(y_), z(z_) {}
	point3d<T> &operator=(const point3d<T> &t) {
		x = t.x, y = t.y, z = t.z;
		return *this;
	}
	point3d<T> &operator+=(const point3d<T> &t) {
		x += t.x, y += t.y, z += t.z;
		return *this;
	}
	point3d<T> &operator-=(const point3d<T> &t) {
		x -= t.x, y -= t.y, z -= t.z;
		return *this;
	}
	point3d<T> &operator*=(T t) {
		x *= t, y *= t, z *= t;
		return *this;
	}
	point3d<T> &operator/=(T t) {
		x /= t, y /= t, z /= t;
		return *this;
	}
	point3d<T> operator-(const point3d<T> &t) const {
		return {x - t.x, y - t.y, z - t.z};
	}
	point3d<T> operator+(const point3d<T> &t) const {
		return {x + t.x, y + t.y, z + t.z};
	}
	point3d<T> operator*(T t) const { return {x * t, y * t, z * t}; }
	point3d<T> operator/(T t) const { return {x / t, y / t, z / t}; }
	T dot(const point3d<T> &b) const { return x * b.x + y * b.y + z * b.z; }
	T operator|(const point3d<T> &b) const { return dot(b); }
	point3d<T> cross(const point3d<T> &b) const {
		return {y * b.z - z * b.y, z * b.x - x * b.z, x * b.y - y * b.x};
	}
	point3d<T> operator^(const point3d<T> &b) const { return cross(b); }
	T triple(const point3d<T> &a, const point3d<T> &b) const {
		return dot(a ^ b);
	}
	bool nonzero() const { return x != 0 || y != 0 || z != 0; }
	T norm() const { return dot(*this); }
	T sq_dist(const point3d<T> &b) const { return (*this - b).norm(); }
	double abs() const { return sqrt((double)norm()); }
	double dist(const point3d<T> &b) const { return (*this - b).abs(); }
	point3d<T> unit() const { return *this / this->abs(); }
	double proj(const point3d<T> &b) const { return (double)dot(b) / b.abs(); }
	double angle(const point3d<T> &b) const {
		return acos(clamp((double)dot(b) / this->abs() / b.abs(), -1.0, 1.0));
	}
	point3d<T> rotate_z(double a) const {
		return {(T)(cos(a) * x - sin(a) * y), (T)(sin(a) * x + cos(a) * y), z};
	}
	point3d<T> rotate_x(double a) const {
		return {x, (T)(cos(a) * y - sin(a) * z), (T)(sin(a) * y + cos(a) * z)};
	}
	point3d<T> rotate_y(double a) const {
		return {(T)(cos(a) * x + sin(a) * z), y, (T)(-sin(a) * x + cos(a) * z)};
	}
};
template <typename T> point3d<T> operator*(T a, point3d<T> b) { return b * a; }

template<typename T>
struct segment {
	point2d<T> P;
	point2d<T> Q;
	const T INF = numeric_limits<T>::max();
	segment(point2d<T> P, point2d<T> Q): P(P), Q(Q) {}
	int sign(T x, T eps = 0) { return x > eps ? 1 : x < -eps ? -1 : 0; }
	bool contain(point2d<T> p, T eps = 0) {
		return ((P - p)|(Q - p)) <= (T)0 and abs(((Q - P)^(p - P))) <= eps;
	}
	bool intersect(segment<T> b) {
		if (this->contain(b.P) or this->contain(b.Q) or b.contain(P) or b.contain(Q))
				return true;
		return sign((((b.P) - P))^((Q - P)))*sign(((b.Q - P)^(Q - P))) < 0 and
					sign(((P - b.Q)^(b.Q - b.P)))*sign(((Q- b.P)^(b.Q - b.P))) < 0;
	}
	point2d<T> intersection(segment<T> b) {
		if(this->intersect(b))
			return (((b.Q-b.P)^(Q-b.P))*P + ((P-b.P)^(b.Q-b.P))*Q)/((P-Q)^(b.Q-b.P));
		return {INF, INF};
	}
};

struct halfplane {
	point2d<ld> p, pq;
	ld angle;
	halfplane() {}
	halfplane(point2d<ld> &a, point2d<ld> &b) : p(a), pq(b - a) {
		angle = atan2l(pq.y, pq.x);
	}
	bool out(point2d<ld> r) { return ((pq) ^ (r - p)) < -eps; }
	bool operator<(halfplane &e) { return angle < e.angle; }
	friend point2d<ld> inter(halfplane &s, halfplane &t) {
		ld alpha = ((t.p - s.p) ^ t.pq) / ((s.pq) ^ (t.pq));
		return s.p + (s.pq * alpha);
	}
};

template <typename T> struct circle {
	point2d<T> c;
	T r;
	circle() : c(), r(0) {}
	circle(point2d<T> c_, T r_) : c(c_), r(r_) {}
	circle(point2d<T> a, point2d<T> b, point2d<T> p) {
		point2d<T> ab = b - a, ap = p - a;
		T d = 2 * (ab ^ ap);
		if (sign(d) == 0) {
			c = point2d<T>();
			r = 0;
			return;
		}
		T s = ab.norm(), t = ap.norm();
		c = a + point2d<T>(ap.y * s - ab.y * t, ab.x * t - ap.x * s) / d;
		r = c.sqdist(a);
		r = sqrtl(r);
	}
};

template<class T>
ld line_dist(point2d<T> a, point2d<T> b, point2d<T> p) {
	return (ld)((b-a)^(p-a)) / (b-a).abs();
}

using P = point2d<ld>;
ld seg_dist(P s, P e, P p) {
	if (s.sqdist(e) < 1e-18) return (p-s).abs();
	auto d = (e-s).norm();
	auto t = min(d, max((ld)0.0, (p-s)|(e-s)));
	return ((p-s)*d - (e-s)*t).abs() / d;
}

template <typename T> struct sphere {
	point3d<T> center;
	ld radius;
	sphere() : center(), radius(0) {}
	sphere(point3d<T> c, ld r) : center(c), radius(r) {}
	bool contains(const point3d<T> &pt) const {
		return center.sq_dist(pt) <= radius * radius + 1e-9;
	}
};

template<typename T>
vector<point2d<T>> convex_hull(vector<point2d<T>> cloud, bool ac = 0) {
	int n = cloud.size(), k = 0;
	sort(cloud.begin(), cloud.end(), [](point2d<T> &a, point2d<T> &b) {
		return a.x < b.x or (a.x == b.x and a.y < b.y);
	});
	if (n <= 2) return cloud;
	bool allCollinear = true;
	for (int i = 2; i < n; ++i) {
		if (((cloud[1] - cloud[0]) ^ (cloud[i] - cloud[0])) != 0) {
			allCollinear = false; break;
		}
	}
	if (allCollinear) return ac ? cloud : vector<point2d<T>>{cloud[0], cloud.back()};
	vector<point2d<T>> ch(2 * n);
	auto process = [&](int st, int end, int stp, int t, auto cmp) {
		for (int i = st; i != end; i += stp) {
			while (k >= t and cmp(ch[k - 1], ch[k - 2], cloud[i])) k--;
			ch[k++] = cloud[i];
		}
	};
	process(0, n, 1, 2, [&](auto a, auto b, auto c) {
		return ((a - b) ^ (c - b)) < (ac ? 0 : 1);
	});
	process(n - 2, -1, -1, k + 1, [&](auto a, auto b, auto c) {
		return ((a - b) ^ (c - b)) < (ac ? 0 : 1);
	});
	ch.resize(k - 1);
	return ch;
}

template <typename T> int in_convex(vector<point2d<T>> &P, point2d<T> q) {
	int n = P.size();
	if (n < 3) return -1;
	point2d<T> q0 = q - P[0];
	T c1 = (P[1] - P[0]) ^ q0, c2 = (P[n - 1] - P[0]) ^ q0;
	if (c1 < 0 || c2 > 0) return -1;
	int l = 1, r = n - 1;
	while (r - l > 1) {
		int mid = (l + r) / 2;
		((P[mid] - P[0]) ^ q0) >= 0 ? l = mid : r = mid;
	}
	T c = (P[l + 1] - P[l]) ^ (q - P[l]);
	return c < 0 ? -1 : (c == 0 || c1 == 0 || c2 == 0 ? 0 : 1);
}

pair<ll, ll> lattice_points(vector<point2d<ll>> &P) {
	P.push_back(P.front());
	ll area = 0, bounds = 0;
	for(int i = 0; i < (int)P.size()-1; ++i) {
		area += P[i]^(P[i+1]);
		point2d<ll> p = P[i+1]-P[i];
		bounds += abs(__gcd(p.x, p.y));
	}
	ll inside = (abs(area) - bounds + 2)/2;
	P.pop_back();
	return {inside, bounds};
}

template <typename T>
vector<point2d<T>> minkowski(vector<point2d<T>> &p, vector<point2d<T>> &q) {
	vector<point2d<T>> v;
	if (min(p.size(), q.size()) < 3) {
		for (auto &a : p) for (auto &b : q)
			v.push_back(a + b);
		return convex_hull(v);
	}
	auto reorder = [](vector<point2d<T>> &v) {
		if (((v[1] - v[0]) ^ (v[2] - v[0])) < 0)
			reverse(v.begin(), v.end());
		int pos = 0;
		for (int i = 1; i < (int)v.size(); i++)
			if (pair{v[i].y, v[i].x} < pair{v[pos].y, v[pos].x})
				pos = i;
		rotate(v.begin(), v.begin() + pos, v.end());
	};
	reorder(p), reorder(q);
	for (int i = 0; i < 2; i++)
		p.push_back(p[i]), q.push_back(q[i]);
	int i = 0, j = 0;
	while (i + 2 < p.size() or j + 2 < q.size()) {
		v.push_back(p[i] + q[j]);
		T c = (p[i + 1] - p[i]) ^ (q[j + 1] - q[j]);
		if (c >= 0 and i + 2 < p.size()) i++;
		if (c <= 0 and j + 2 < q.size()) j++;
	}
	return v;
}

#define sq(x) ((x)*(x))
template <typename T>
pair<point2d<T>, point2d<T>> nearest_points(vector<point2d<T>> &P, int l, int r) {
	const T INF = 1e10;
	if (r-l == 1) return {P[l], P[r]};
	if (l >= r) return {{INF, INF}, {-INF, -INF}};
	int m = (l+r)/2;
	pair<point2d<T>, point2d<T>> D1, D2, D;
	D1 = nearest_points(P, l, m);
	D2 = nearest_points(P, m+1, r);
	D = (D1.first.sqdist(D1.second) <= D2.first.sqdist(D2.second) ? D1 : D2);
	T d = D.first.sqdist(D.second), x_center = (P[m].x + P[m+1].x)/2;
	vector<point2d<T>> Pk;
	for (int i = l; i <= r; i++)
		if (sq(P[i].x-x_center) <= d)
			Pk.push_back(P[i]);
	sort(Pk.begin(), Pk.end(), [](const point2d<T> p1, const point2d<T> p2) {
		return p1.y != p2.y ? p1.y < p2.y : p1.x < p2.x;
	});
	for(int i = 0; i < Pk.size(); ++i) {
		for(int j = i-1; j >= 0; --j) {
			if(sq(Pk[i].y-Pk[j].y) > d) break;
			if(Pk[i].sqdist(Pk[j]) <= D.first.sqdist(D.second))
				D = {Pk[i],Pk[j]};
		}
		for(int j = i+1; j < Pk.size(); ++j) {
			if(sq(Pk[i].y-Pk[j].y) > d) break;
			if(Pk[i].sqdist(Pk[j]) <= D.first.sqdist(D.second))
				D = {Pk[i],Pk[j]};
		}
	}
	return D;
}
template <typename T>
pair<point2d<T>, point2d<T>> nearest_points(vector<point2d<T>> &P) {
	sort(P.begin(), P.end(), [](const point2d<T> &p1, const point2d<T> &p2) {
		if (p1.x == p2.x) return p1.y < p2.y;
		return p1.x < p2.x;
	});
	return nearest_points(P, 0, P.size()-1);
}

template <typename T>
int semiplane(point2d<T> p) { return p.y > 0 or (p.y == 0 and p.x > 0); }
template <typename T>
void order_by_angle(vector<point2d<T>> &P) {
	sort(P.begin(), P.end(), [](point2d<T> &p1, point2d<T> &p2) {
		int s1 = semiplane(p1), s2 = semiplane(p2);
		return s1 != s2 ? s1 > s2 : (p1^p2) > 0;
	});
}

template <typename T>
void order_by_slope(vector<point2d<T>> &P) {
	sort(P.begin(), P.end(), [](const point2d<T> &p1, const point2d<T> &p2) {
		Fraction<T> r1 = Fraction<T>(p1.x, p1.y), r2 = Fraction<T>(p2.x, p2.y);
		return r2 < r1;
	});
}

template<typename T>
int point_inside_polygon(vector<point2d<T>> &P, point2d<T> q) {
	int N = P.size(), cnt = 0;
	for(int i = 0; i < N; i++) {
		int j = (i == N-1 ? 0 : i+1);
		segment<T> s(P[i], P[j]);
		if(s.contain(q)) return 0;
		if(P[i].x <= q.x and q.x < P[j].x and q.cross(P[i], P[j]) < 0) cnt++;
		else if(P[j].x <= q.x and q.x < P[i].x and q.cross(P[j], P[i]) < 0) cnt++;
	}
	return cnt&1 ? 1 : -1;
}

template<typename T>
T polygon_area(vector<point2d<T>> P, bool x2 = 0) {
	if (P.size() < 3) return (T)0;
	T area = 0;
	for(int i = 0; i < P.size()-1; ++i)
		area += P[i]^(P[i+1]);
	area += (P.back())^(P.front());
	return abs(area)/ (x2 ? 1 : 2);
}

const ld inf = 1e18;
const ld eps = 1e-9;
vector<point2d<ld>> hp_intersect(vector<halfplane> &H) {
	point2d<ld> box[4] = {{inf, inf}, {-inf, inf}, {-inf, -inf}, {inf, -inf}};
	for (int i = 0; i < 4; i++) {
		halfplane aux(box[i], box[(i + 1) % 4]);
		H.push_back(aux);
	}
	sort(H.begin(), H.end());
	deque<halfplane> dq;
	int len = 0;
	for (int i = 0; i < H.size(); i++) {
		while (len > 1 && H[i].out(inter(dq[len - 1], dq[len - 2])))
			dq.pop_back(), --len;
		while (len > 1 && H[i].out(inter(dq[0], dq[1])))
			dq.pop_front(), --len;
		if (len > 0 && fabsl((H[i].pq ^ dq[len - 1].pq)) < eps) {
			if ((H[i].pq | dq[len - 1].pq) < 0.0)
				return vector<point2d<ld>>();
			if (H[i].out(dq[len - 1].p))
				dq.pop_back(), --len;
			else
				continue;
		}
		dq.push_back(H[i]), ++len;
	}
	while (len > 2 && dq[0].out(inter(dq[len - 1], dq[len - 2])))
		dq.pop_back(), --len;
	while (len > 2 && dq[len - 1].out(inter(dq[0], dq[1])))
		dq.pop_front(), --len;
	if (len < 3)
		return vector<point2d<ld>>();
	vector<point2d<ld>> ret(len);
	for (int i = 0; i + 1 < len; i++)
		ret[i] = inter(dq[i], dq[i + 1]);
	ret.back() = inter(dq[len - 1], dq[0]);
	return ret;
}

circle<ld> minimum_enclosing_circle(vector<point2d<ld>> p) {
	mt19937 rng(chrono::steady_clock::now().time_since_epoch().count());
	shuffle(p.begin(), p.end(), rng);
	int n = p.size();
	if (n == 0) return circle<ld>();
	circle<ld> cur(p[0], 0);
	auto out = [&](int i) { return sign(sqrtl(cur.c.sqdist(p[i])) - cur.r) > 0; };
	for (int i = 1; i < n; i++) if (out(i)) {
		cur = circle<ld>(p[i], 0);
		for (int j = 0; j < i; j++ ) if (out(j)) {
			cur = circle<ld>((p[i] + p[j]) / 2, sqrtl(p[i].sqdist(p[j])) / 2);
			for (int k = 0; k < j; k++) if (out(k))
				cur = circle<ld>(p[i], p[j], p[k]);
		}
	}
	return cur;
}

template <typename T>
sphere<T> minimum_enclosing_sphere(vector<point3d<T>> p, int it = 100000) {
	int n = p.size();
	if (n == 0) return sphere<T>();
	if (n == 1) return sphere<T>(p[0], 0);
	point3d<T> c(0, 0, 0);
	for (int i = 0; i < n; i++)
		c = c + p[i];
	c = c / (ld)n;
	ld ratio = 0.1;
	while (it--) {
		int pos = 0;
		for (int i = 1; i < n; i++) {
			if (c.sq_dist(p[i]) > c.sq_dist(p[pos]))
				pos = i;
		}
		c = c + (p[pos] - c) * ratio;
		ratio *= 0.998;
	}
	return sphere(c, c.dist(p[pos]));
}

template <typename T> struct convex_hull_3d {
	using pt = point3d<T>;
	struct edge;
	struct face {
		int a, b, c;
		pt q;
		edge *e1, *e2, *e3;
		vector<int> points;
		int dead = 1e9;
		face(int a, int b, int c, pt pa, pt pb, pt pc)
				: a(a), b(b), c(c) {
			q = (pb - pa) ^ (pc - pa);
			e1 = e2 = e3 = nullptr;
		}
	};
	struct edge { edge *rev; face *f; };
	vector<pt> p;
	vector<face *> f;
	bool degenerate = false;
	static void glue(face *F1, face *F2, edge *&e1, edge *&e2) {
		e1 = new edge; e2 = new edge;
		e1->rev = e2; e2->rev = e1;
		e1->f = F2; e2->f = F1;
	}
	void prepare() {
		int n = (int)p.size();
		mt19937 rng(42);
		shuffle(p.begin(), p.end(), rng);
		vector<int> ve = {0};
		for (int i = 1; i < n && (int)ve.size() < 4; i++) {
			if (ve.size() == 1) {
				if ((p[ve[0]] - p[i]).nonzero()) ve.push_back(i);
			} else if (ve.size() == 2) {
				if (((p[ve[1]] - p[ve[0]]) ^ (p[i] - p[ve[0]])).nonzero())
					ve.push_back(i);
			} else {
				if ((p[i] - p[ve[0]]).dot((p[ve[1]] - p[ve[0]]) ^ (p[ve[2]] - p[ve[0]])) != 0)
					ve.push_back(i);
			}
		}
		if ((int)ve.size() < 4) { degenerate = true; return; }
		vector<pt> ve2;
		for (int i : ve) ve2.push_back(p[i]);
		reverse(ve.begin(), ve.end());
		for (int i : ve) p.erase(p.begin() + i);
		p.insert(p.begin(), ve2.begin(), ve2.end());
	}
	convex_hull_3d() {}
	convex_hull_3d(vector<pt> points) : p(move(points)) { build_hull(); }
	void build_hull() {
		int n = (int)p.size();
		prepare();
		if (degenerate) return;
		vector<face *> new_face(n, nullptr);
		vector<vector<face *>> conflict(n);
		auto add_face = [&](int a, int b, int c) {
			face *F = new face(a, b, c, p[a], p[b], p[c]);
			f.push_back(F); return F;
		};
		face *F1 = add_face(0, 1, 2);
		face *F2 = add_face(0, 2, 1);
		glue(F1, F2, F1->e1, F2->e3);
		glue(F1, F2, F1->e2, F2->e2);
		glue(F1, F2, F1->e3, F2->e1);
		for (int i = 3; i < n; i++) {
			for (face *F : {F1, F2}) {
				T Q = (p[i] - p[F->a]).dot(F->q);
				if (Q > 0) conflict[i].push_back(F);
				if (Q >= 0) F->points.push_back(i);
			}
		}
		for (int i = 3; i < n; i++) {
			for (face *F : conflict[i]) F->dead = min(F->dead, i);
			int v = -1;
			for (face *F : conflict[i]) {
				if (F->dead != i) continue;
				int parr[3] = {F->a, F->b, F->c};
				edge *earr[3] = {F->e1, F->e2, F->e3};
				for (int j = 0; j < 3; j++) {
					int j2 = (j + 1) % 3;
					if (earr[j]->f->dead > i) {
						face *Fn = new_face[parr[j]] = add_face(parr[j], parr[j2], i);
						set_union(F->points.begin(), F->points.end(),
											earr[j]->f->points.begin(), earr[j]->f->points.end(),
											back_inserter(Fn->points));
						Fn->points.erase(
								stable_partition(Fn->points.begin(), Fn->points.end(),
																[&](int k) { return k > i && (p[k] - p[Fn->a]).dot(Fn->q) > 0; }),
								Fn->points.end());
						for (int k : Fn->points) conflict[k].push_back(Fn);
						earr[j]->rev->f = Fn;
						Fn->e1 = earr[j];
						v = parr[j];
					}
				}
			}
			if (v == -1) continue;
			while (new_face[v]->e2 == nullptr) {
				int u = new_face[v]->b;
				glue(new_face[v], new_face[u], new_face[v]->e2, new_face[u]->e3);
				v = u;
			}
		}
		f.erase(remove_if(f.begin(), f.end(),
											[&](face *F) { return F->dead < n; }), f.end());
	}
	int num_faces() const { return (int)f.size(); }
	double area() const {
		double res = 0;
		for (face *F : f) res += F->q.abs() / 2.0;
		return res;
	}
	double volume() const {
		double vol = 0;
		for (face *F : f) vol += p[F->a].dot(F->q);
		return std::abs(vol) / 6.0;
	}
	vector<array<int, 3>> faces() const {
		vector<array<int, 3>> res;
		for (face *F : f) res.push_back({F->a, F->b, F->c});
		return res;
	}
};

using P = point2d<ld>;
bool circle_inter(P a, P b, ld r1, ld r2,
		pair<P,P>* out) {
	if (a.sqdist(b) < 1e-18) return false;
	P vec = b - a;
	ld d2 = vec.norm(), sum = r1+r2, dif = r1-r2,
		p = (d2 + r1*r1 - r2*r2) / (d2*2),
		h2 = r1*r1 - p*p*d2;
	if (sum*sum < d2 || dif*dif > d2) return false;
	P per = {-vec.y, vec.x};
	P mid = a + vec*p;
	per = per * sqrt(fmax(0, h2) / d2);
	*out = {mid + per, mid - per};
	return true;
}

using P = point2d<ld>;
vector<pair<P,P>> tangents(P c1, ld r1,
		P c2, ld r2) {
	P d = c2 - c1;
	ld dr = r1 - r2, d2 = d.norm(), h2 = d2 - dr*dr;
	if (d2 < 1e-18 || h2 < 0) return {};
	vector<pair<P,P>> out;
	P perp = {-d.y, d.x};
	for (ld sign : {-1.0, 1.0}) {
		P v = (d*dr + perp*sqrt(h2)*sign) / d2;
		out.push_back({c1 + v*r1, c2 + v*r2});
	}
	if (h2 < 1e-18) out.pop_back();
	return out;
}

using P = point2d<ld>;
ld circle_poly(P c, ld r, vector<P>& ps) {
	auto arg = [](P p, P q) {
		return atan2(p^q, p|q);
	};
	auto tri = [&](P p, P q) {
		auto r2 = r*r/2;
		P d = q - p;
		auto a = (d|p)/d.norm(), b = (p.norm()-r*r)/d.norm();
		auto det = a*a - b;
		if (det <= 0) return arg(p,q) * r2;
		auto s = max(0.0L, -a-sqrt(det));
		auto t = min(1.0L, -a+sqrt(det));
		if (t < 0 or 1 <= s) return arg(p,q) * r2;
		P u = p + d*s, v = p + d*t;
		return arg(p,u)*r2 + (u^v)/2 + arg(v,q)*r2;
	};
	ld sum = 0;
	int n = ps.size();
	for (int i = 0; i < n; i++)
		sum += tri(ps[i]-c, ps[(i+1)%n]-c);
	return sum;
}

using P = point2d<ld>;
P polygon_center(vector<P>& v) {
	P res(0, 0); ld A = 0;
	int n = v.size();
	for (int i = 0, j = n-1; i < n; j = i++) {
		res = res + (v[i]+v[j]) * (v[j]^v[i]);
		A += v[j]^v[i];
	}
	return res / A / 3;
}

using P = point2d<ld>;
vector<P> polygon_cut(vector<P>& poly, P s, P e) {
	vector<P> res;
	int n = poly.size();
	for (int i = 0; i < n; i++) {
		P cur = poly[i], prev = i ? poly[i-1] : poly.back();
		auto a = s.cross(e, cur), b = s.cross(e, prev);
		if ((a < 0) != (b < 0))
			res.push_back(cur + (prev-cur) * (a / (a-b)));
		if (a < 0) res.push_back(cur);
	}
	return res;
}

template<class T>
array<point2d<T>,2> hull_diameter(vector<point2d<T>>& S) {
	int n = S.size(), j = n < 2 ? 0 : 1;
	pair<T, array<point2d<T>,2>> res = {0, {S[0], S[0]}};
	for (int i = 0; i < j;)
		for (;; j = (j+1)%n) {
			res = max(res, {S[i].sqdist(S[j]), {S[i], S[j]}});
			if (((S[(j+1)%n]-S[j])^(S[i+1]-S[i])) >= 0)
				{ i++; break; }
		}
	return res.second;
}

template <typename T> struct delaunay {
	using pt = point2d<T>;
	using lll = __int128_t;
	struct Quad {
		Quad *rot, *o;
		pt p; int id; bool mark;
		pt& F() { return rot->rot->p; }
		int& Fi() { return rot->rot->id; }
		Quad*& r() { return rot->rot; }
		Quad* prev() { return rot->o->rot; }
		Quad* next() { return r()->prev(); }
	};
	Quad* pool;
	bool circ(pt p, pt a, pt b, pt c) {
		lll p2=p.norm(), A=a.norm()-p2, B=b.norm()-p2, C=c.norm()-p2;
		return p.cross(a,b)*C + p.cross(b,c)*A + p.cross(c,a)*B > 0;
	}
	Quad* makeEdge(pt orig, int oi, pt dest, int di) {
		auto nq = [&]() { return new Quad{nullptr,nullptr,{}, -1, false}; };
		Quad* r;
		if (pool) { r = pool; pool = r->o; }
		else { r = nq(); r->rot = nq(); r->rot->rot = nq(); r->rot->rot->rot = nq(); }
		r->r()->r() = r; r->rot->rot->rot->rot = r;
		pt arb{(T)1e18, (T)1e18};
		Quad* c = r;
		for (int i = 0; i < 4; i++) {
			c = c->rot; c->p = arb; c->id = -1;
			c->o = (i & 1) ? c : c->r();
		}
		r->p = orig; r->id = oi; r->F() = dest; r->Fi() = di;
		return r;
	}
	void splice(Quad* a, Quad* b) {
		swap(a->o->rot->o, b->o->rot->o); swap(a->o, b->o);
	}
	Quad* connect(Quad* a, Quad* b) {
		Quad* q = makeEdge(a->F(), a->Fi(), b->p, b->id);
		splice(q, a->next()); splice(q->r(), b); return q;
	}
	pair<Quad*,Quad*> rec(vector<pt>& s, vector<int>& ids, int lo, int hi) {
		int sz = hi - lo;
		if (sz <= 3) {
			Quad* a = makeEdge(s[lo],ids[lo], s[lo+1],ids[lo+1]);
			Quad* b = makeEdge(s[lo+1],ids[lo+1], s[lo+sz-1],ids[lo+sz-1]);
			if (sz == 2) return {a, a->r()};
			splice(a->r(), b);
			auto side = s[lo].cross(s[lo+1], s[lo+2]);
			Quad* c = side ? connect(b, a) : nullptr;
			return {side<0 ? c->r() : a, side<0 ? c : b->r()};
		}
		int mid = lo + sz/2;
		auto [ra, A] = rec(s, ids, lo, mid);
		auto [B, rb] = rec(s, ids, mid, hi);
		while ((B->p.cross(A->F(), A->p)<0 && (A=A->next())) ||
					(A->p.cross(B->F(), B->p)>0 && (B=B->r()->o)));
		Quad* base = connect(B->r(), A);
		if (A->p.x==ra->p.x && A->p.y==ra->p.y) ra = base->r();
		if (B->p.x==rb->p.x && B->p.y==rb->p.y) rb = base;
		auto valid = [&](Quad* e) { return e->F().cross(base->F(), base->p) > 0; };
		for (;;) {
			Quad* LC = base->r()->o;
			if (valid(LC)) while (circ(LC->o->F(), base->F(), base->p, LC->F()))
				{ Quad* t=LC->o; splice(LC,LC->prev()); splice(LC->r(),LC->r()->prev()); LC->o=pool; pool=LC; LC=t; }
			Quad* RC = base->prev();
			if (valid(RC)) while (circ(RC->prev()->F(), base->F(), base->p, RC->F()))
				{ Quad* t=RC->prev(); splice(RC,RC->prev()); splice(RC->r(),RC->r()->prev()); RC->o=pool; pool=RC; RC=t; }
			if (!valid(LC) && !valid(RC)) break;
			if (!valid(LC) || (valid(RC) && circ(RC->F(), base->F(), base->p, LC->F())))
				base = connect(RC, base->r());
			else base = connect(base->r(), LC->r());
		}
		return {ra, rb};
	}
	int n;
	vector<array<int, 3>> tri;
	delaunay() : pool(nullptr), n(0) {}
	delaunay(vector<T> &px, vector<T> &py) : pool(nullptr), n(0) { build(px, py); }
	void build(vector<T> &px, vector<T> &py) {
		n = (int)px.size(); tri.clear(); pool = nullptr;
		if (n < 2) return;
		vector<int> ord(n); iota(ord.begin(), ord.end(), 0);
		sort(ord.begin(), ord.end(), [&](int a, int b) {
			return px[a]<px[b] || (px[a]==px[b] && py[a]<py[b]);
		});
		vector<pt> sp(n); vector<int> si(n);
		for (int i = 0; i < n; i++) { sp[i] = {px[ord[i]], py[ord[i]]}; si[i] = ord[i]; }
		Quad* e = rec(sp, si, 0, n).first;
		vector<Quad*> q = {e};
		int qi = 0;
		while (e->o->F().cross(e->F(), e->p) < 0) e = e->o;
		auto add = [&](Quad* e) {
			Quad* c = e; vector<int> face;
			do { c->mark=1; face.push_back(c->id); q.push_back(c->r()); c=c->next(); } while (c!=e);
			if ((int)face.size()==3) tri.push_back({face[0],face[1],face[2]});
		};
		add(e);
		while (qi < (int)q.size()) if (!(e=q[qi++])->mark) add(e);
	}
};

template <typename T> struct delaunay_graph : delaunay<T> {
	vector<vector<int>> adj;
	delaunay_graph() {}
	delaunay_graph(vector<T> &px, vector<T> &py) { build(px, py); }
	void build(vector<T> &px, vector<T> &py) {
		delaunay<T>::build(px, py);
		adj.assign(this->n, {});
		for (auto &t : this->tri)
			for (int i = 0; i < 3; i++) for (int j = i+1; j < 3; j++) {
				adj[t[i]].push_back(t[j]); adj[t[j]].push_back(t[i]);
			}
		for (auto &v : adj) { sort(v.begin(), v.end()); v.erase(unique(v.begin(), v.end()), v.end()); }
	}
	int walk(vector<T> &px, vector<T> &py, T qx, T qy) const {
		auto d2 = [&](int i) { return (qx-px[i])*(qx-px[i]) + (qy-py[i])*(qy-py[i]); };
		int cur = 0; T best = d2(0);
		for (bool ok = true; ok; ) { ok = false;
			for (int nb : adj[cur]) { T d = d2(nb); if (d < best) { best=d; cur=nb; ok=true; break; } }
		}
		return cur;
	}
	vector<int> locate(vector<T> &px, vector<T> &py, T qx, T qy) const {
		auto d2 = [&](int i) { return (qx-px[i])*(qx-px[i]) + (qy-py[i])*(qy-py[i]); };
		int v = walk(px, py, qx, qy);
		T best = d2(v);
		vector<int> res = {v};
		vector<bool> vis(this->n, false);
		vis[v] = true;
		for (int qi = 0; qi < (int)res.size(); qi++)
			for (int nb : adj[res[qi]])
				if (!vis[nb]) { vis[nb] = true; if (d2(nb) == best) res.push_back(nb); }
		sort(res.begin(), res.end());
		return res;
	}
};

template <class I> vector<int> LIS(const vector<I> &S) {
	if (S.empty())
		return {};
	vector<int> prev(S.size());
	vector<pair<I, int>> res;
	for (int i = 0; i < S.size(); i++) {
		auto it = lower_bound(res.begin(), res.end(), pair<I, int>{S[i], i});
		if (it == res.end())
			res.emplace_back(), it = res.end() - 1;
		*it = {S[i], i};
		prev[i] = (it == res.begin() ? 0 : (it - 1)->second);
	}
	int L = res.size(), cur = res.back().second;
	vector<int> ans(L);
	while (L--)
		ans[L] = cur, cur = prev[cur];
	return ans;
}

const ll INF = 1e18;
ll egg_drop(int h, int k) {
	vector<vector<ll>> dp(h + 1, vector<ll>(k + 1, INF));
	for (int j = 0; j <= k; j++) dp[0][j] = 0;
	for (int j = 1; j <= k; j++) {
		for (int i = 1; i <= h; i++) {
			int lo = 1, hi = i;
			while (lo <= hi) {
				int mid = (lo + hi) / 2;
				ll br = dp[mid - 1][j - 1], sv = dp[i - mid][j];
				dp[i][j] = min(dp[i][j], 1 + max(br, sv));
				(br < sv) ? lo = mid + 1 : hi = mid - 1;
			}
		}
	}
	return dp[h][k];
}
ll egg_drop_fast(int h, int k) {
	vector<ll> cur(k + 1, 0), nxt(k + 1);
	for (int t = 1; t <= h; t++) {
		for (int j = 1; j <= k; j++) {
			nxt[j] = cur[j - 1] + cur[j] + 1;
			if (nxt[j] >= h) return t;
		}
		swap(cur, nxt);
	}
	return h;
}

const ll INF = 1e18;
int n;
vector<ll> dp, ndp;
ll cost(int l, int r);
void dac_solve(int l, int r, int optl, int optr) {
	if (l > r) return;
	int mid = (l + r) / 2, opt = optl;
	ndp[mid] = INF;
	for (int k = optl; k <= min(mid - 1, optr); k++) {
		ll val = dp[k] + cost(k + 1, mid);
		if (val < ndp[mid]) ndp[mid] = val, opt = k;
	}
	dac_solve(l, mid - 1, optl, opt);
	dac_solve(mid + 1, r, opt, optr);
}
ll dac_dp(int layers) {
	dp.assign(n + 1, INF); dp[0] = 0;
	for (int i = 0; i < layers; i++) {
		ndp.assign(n + 1, INF);
		dac_solve(1, n, 0, n - 1);
		swap(dp, ndp);
	}
	return dp[n];
}

const ll INF = 1e18;
int n;
vector<vector<ll>> dp;
vector<vector<int>> opt;
ll cost(int i, int j);
ll knuth_dp() {
	dp.assign(n, vector<ll>(n, 0));
	opt.assign(n, vector<int>(n));
	for (int i = 0; i < n; i++) opt[i][i] = i;
	for (int len = 2; len <= n; len++) {
		for (int i = 0; i + len <= n; i++) {
			int j = i + len - 1;
			dp[i][j] = INF;
			for (int k = opt[i][j - 1]; k <= opt[min(i + 1, j)][j]; k++) {
				ll val = dp[i][k] + (k + 1 <= j ? dp[k + 1][j] : 0) + cost(i, j);
				if (val < dp[i][j]) dp[i][j] = val, opt[i][j] = k;
			}
		}
	}
	return dp[0][n - 1];
}

struct convex_hull_trick {
	vector<ll> A, B;
	const ll inf = numeric_limits<ll>::max()/4;
	double cross(ll i, ll j, ll k) {
		return 1.0*(A[j] - A[i]) * (B[k] - B[i]) - 1.0*(A[k] - A[i]) * (B[j] - B[i]);
	}
	void add(ll a, ll b) {
		A.push_back(a), B.push_back(b);
		while(A.size() > 2 and cross(A.size() - 3, A.size() - 2, A.size() - 1) <= 0)
			A.erase(A.end() - 2), B.erase(B.end() - 2);
	}
	ll query(ll x) {
		if(A.empty()) return inf;
		ll l = 0, r = A.size() - 1;
		while (l < r) {
			ll mid = (l + r)/2;
			ll f1 = A[mid] * x + B[mid];
			ll f2 = A[mid + 1] * x + B[mid + 1];
			if(f1 > f2) l = mid + 1;
			else r = mid;
		}
		return A[l] * x + B[l];
	}
};

struct Line{
	ll a,b;
	Line(ll _a, ll _b) : a(_a), b(_b) {};
	ll eval(ll x){ return a*x + b;}
};
struct li_chao{
	const ll INF = 1e18;
	ll L,R;
	vector<Line> st;
	li_chao(ll l,ll r){
		L = l, R = r+1;
		st = vector<Line>(4*(r - l + 1),Line(0,INF));
	};
	void add(Line nw, ll v, ll l, ll r){
		ll m = (l+r)/2;
		bool lc = nw.eval(l) < st[v].eval(l);
		bool mc = nw.eval(m) < st[v].eval(m);
		if(mc) swap(nw,st[v]);
		if(r - l == 1) return;
		if(lc != mc) add(nw,2*v,l,m);
		else add(nw,2*v + 1,m,r);
	}
	ll get(ll x, ll v, ll l, ll r){
		ll m = (l+r)/2;
		if(r - l == 1) return st[v].eval(x);
		if(x < m) return min(st[v].eval(x),get(x,2*v,l,m));
		return min(st[v].eval(x),get(x,2*v+1,m,r));
	}
	void add(ll a, ll b){add(Line(a,b),1,L,R);};
	ll get(ll x){return get(x,1,L,R);};
};

using ll = long long;
const ll inf = 2e18;
struct Line {
	ll m, c;
	ll eval(ll x) { return m * x + c; }
};
struct node {
	Line line;
	node *left = nullptr;
	node *right = nullptr;
	node(Line line) : line(line) {}
	void add_segment(Line nw, int l, int r, int L, int R) {
		if (l > r || r < L || l > R)
			return;
		int m = (l + 1 == r ? l : (l + r) / 2);
		if (l >= L and r <= R) {
			bool lef = nw.eval(l) < line.eval(l);
			bool mid = nw.eval(m) < line.eval(m);
			if (mid)
				swap(line, nw);
			if (l == r)
				return;
			if (lef != mid) {
				if (left == nullptr)
					left = new node(nw);
				else
					left->add_segment(nw, l, m, L, R);
			} else {
				if (right == nullptr)
					right = new node(nw);
				else
					right->add_segment(nw, m + 1, r, L, R);
			}
			return;
		}
		if (max(l, L) <= min(m, R)) {
			if (left == nullptr)
				left = new node({0, inf});
			left->add_segment(nw, l, m, L, R);
		}
		if (max(m + 1, L) <= min(r, R)) {
			if (right == nullptr)
				right = new node({0, inf});
			right->add_segment(nw, m + 1, r, L, R);
		}
	}
	ll query_segment(ll x, int l, int r, int L, int R) {
		if (l > r || r < L || l > R)
			return inf;
		int m = (l + 1 == r ? l : (l + r) / 2);
		if (l >= L and r <= R) {
			ll ans = line.eval(x);
			if (l < r) {
				if (x <= m && left != nullptr)
					ans = min(ans, left->query_segment(x, l, m, L, R));
				if (x > m && right != nullptr)
					ans = min(ans, right->query_segment(x, m + 1, r, L, R));
			}
			return ans;
		}
		ll ans = inf;
		if (max(l, L) <= min(m, R)) {
			if (left == nullptr)
				left = new node({0, inf});
			ans = min(ans, left->query_segment(x, l, m, L, R));
		}
		if (max(m + 1, L) <= min(r, R)) {
			if (right == nullptr)
				right = new node({0, inf});
			ans = min(ans, right->query_segment(x, m + 1, r, L, R));
		}
		return ans;
	}
};
struct LiChaoTree {
	int L, R;
	node *root;
	LiChaoTree()
			: L(numeric_limits<int>::min() / 2), R(numeric_limits<int>::max() / 2),
				root(nullptr) {}
	LiChaoTree(int L, int R) : L(L), R(R) { root = new node({0, inf}); }
	void add_line(Line line) { root->add_segment(line, L, R, L, R); }
	void add_segment(Line line, int l, int r) {
		root->add_segment(line, L, R, l, r);
	}
	ll query(ll x) { return root->query_segment(x, L, R, L, R); }
	ll query_segment(ll x, int l, int r) {
		return root->query_segment(x, l, r, L, R);
	}
};

int knapsack(vector<int> w, int t) {
	int a = 0, b = 0, n = w.size(), x;
	while (b < n && a + w[b] <= t) a += w[b++];
	if (b == n) return a;
	int m = *max_element(w.begin(), w.end());
	vector<int> u, v(2*m, -1);
	v[a+m-t] = b;
	for (int i = b; i < n; i++) {
		u = v;
		for (x = 0; x < m; x++)
			v[x+w[i]] = max(v[x+w[i]], u[x]);
		for (x = 2*m; --x > m;)
			for (int j = max(0, u[x]); j < v[x]; j++)
				v[x-w[j]] = max(v[x-w[j]], j);
	}
	for (a = t; v[a+m-t] < 0; a--) ;
	return a;
}

template<class T, class repr>
struct simulated_annealing {
	T val;
	double get_time(){
		return chrono::duration<double>(
			chrono::high_resolution_clock::now().time_since_epoch()
		).count();
	}
	double P(double old_val, double new_val, double temp) { return exp(((old_val-new_val))/temp); }
	simulated_annealing(double time_limit, double t_i, double t_f, repr & q){
		q.init();
		double st = get_time(); val = q.eval();
		while (1){
			double elapsed = get_time()-st;
			if (elapsed > time_limit) break;
			double ela_frac = elapsed/time_limit;
			double temp = t_i*pow(t_f/t_i,ela_frac);
			q.get_neighbor();
			T new_val = q.eval();
			if (new_val < val || ((double)rand())/RAND_MAX < P(val,new_val,temp)){
				val = new_val;
			} else {
				q.rollback();
			}
		}
	}
};

template<
		typename W_t,
		typename T,
		typename Orc1,
		typename Orc2
>
vector<vector<T>> weighted_matroid_intersection(const vector<T> & ground_set, const Orc1 & matroid1, const Orc2 & matroid2){
		int n = ground_set.size();
		vector<vector<T>> res;
		vector<char> in_set(n), in_matroid1(n), in_matroid2(n);
		vector<pair<W_t,int>> dist(n);
		vector<pair<int,int>> edges;
		vector<int> par(n), l, r;
		l.reserve(n);
		r.reserve(n);
		while (1) {
				res.push_back({});
				for (int i = 0; i < n; i++)
						if (in_set[i])
								res.back().push_back(ground_set[i]);
				Orc1 m1 = matroid1;
				Orc2 m2 = matroid2;
				l.clear();
				r.clear();
				for (int i = 0; i < n; i++)
						if (in_set[i]) {
								m1.add(ground_set[i]);
								m2.add(ground_set[i]);
								l.push_back(i);
						} else {
								r.push_back(i);
						}
				fill(in_matroid1.begin(), in_matroid1.end(), 0);
				fill(in_matroid2.begin(), in_matroid2.end(), 0);
				for (int i : r) {
						in_matroid1[i] = m1.independed_with(ground_set[i]);
						in_matroid2[i] = m2.independed_with(ground_set[i]);
				}
				edges.clear();
				for (int i : l) {
						{
								Orc1 m = matroid1;
								for (int j : l)
										if (i != j)
												m.add(ground_set[j]);
								for (int j : r)
										if (m.independed_with(ground_set[j]))
												edges.emplace_back(i, j);
						}
						{
								Orc2 m = matroid2;
								for (int j : l)
										if (i != j)
												m.add(ground_set[j]);
								for (int j : r)
										if (m.independed_with(ground_set[j]))
												edges.emplace_back(j, i);
						}
				}
				static constexpr W_t INF = numeric_limits<W_t>::max();
				fill(dist.begin(), dist.end(), pair{INF, -1});
				fill(par.begin(), par.end(), -1);
				for (int i : r)
						if (in_matroid1[i])
								dist[i] = {-ground_set[i].weight, 0};
				while (1) {
						bool any = false;
						for (auto &[v, u] : edges) {
								if (dist[v].first == INF)
										continue;
								int coeff = in_set[v] ? -1 : 1;
								if (dist[u] > pair{dist[v].first + coeff * ground_set[u].weight, dist[v].second + 1}) {
										par[u] = v;
										dist[u] = {dist[v].first + coeff * ground_set[u].weight, dist[v].second + 1};
										any = 1;
								}
						}
						if (!any)
								break;
				}
				int finish = -1;
				for (int v : r)
						if (in_matroid2[v] && dist[v].first != INF && (finish == -1 || dist[finish] > dist[v]))
								finish = v;
				if (finish == -1)
						break;
				for (; finish != -1; finish = par[finish])
						in_set[finish] ^= 1;
		}
		return res;
}
